                {data.blockers.map((blocker) => (
                  <tr key={blocker.id} className="border-b border-[var(--dash-border-subtle)] align-top">
                    <td className="px-4 py-3">
                      <Badge variant="outline" className={cn("rounded-md", severityClass(blocker.severity))}>
