function formatDate(value: string | null | undefined, locale: Locale) {
  if (!value) return copy[locale].notSet
  return new Intl.DateTimeFormat(locale === "fr" ? "fr-FR" : "en-US", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(value))
}

