        >
          <div className="p-4 text-sm leading-6 text-[var(--dash-text-soft)]">
            <div className="rounded-lg border border-[var(--dash-border-subtle)] bg-[var(--dash-surface-muted)] p-3 font-mono text-xs text-[var(--dash-text)]">
