formatPeriod.source:
function formatPeriod(start: string | null, end: string | null) {
  if (!start && !end) return "Not set"
  if (!start) return `Until ${formatDate(end)}`
  if (!end) return `From ${formatDate(start)}`
  return `${formatDate(start)} - ${formatDate(end)}`
}

