formatNumber.source:
function formatNumber(value: number, locale: Locale) {
  return new Intl.NumberFormat(locale === "fr" ? "fr-FR" : "en-US", {
    maximumFractionDigits: 2,
  }).format(value)
}

formatCurrency.source:
function formatCurrency(value: number, locale: Locale, currency?: string) {
  if (!currency) return "—"
  return new Intl.NumberFormat(locale === "fr" ? "fr-FR" : "en-US", {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(value)
}

formatDate.source:
function formatDate(value: Date | string | null | undefined, locale: Locale, fallback = "Never") {
  if (!value) return fallback
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return fallback

  return new Intl.DateTimeFormat(locale === "fr" ? "fr-FR" : "en-US", {
    dateStyle: "medium",
  }).format(date)
}

isOverCreditLimit.source:
function isOverCreditLimit(customer: CustomerManagementRow) {
  return customer.creditLimit !== null && customer.currentBalance > customer.creditLimit
}

