                    <div className="text-center py-12">
                      <div className="w-16 h-16 bg-[var(--dash-surface)] rounded-full flex items-center justify-center mx-auto mb-4">
                        <Package className="w-8 h-8 text-[var(--dash-text-faint)]" />
                      </div>
                      <h3 className="text-lg font-semibold text-[var(--dash-text)] mb-2">{tr("No orders found", "Aucune commande")}</h3>
                      <p className="text-[var(--dash-text-soft)] mb-6">
                        {searchQuery || statusFilter !== "all"
                          ? tr("No orders match the current filters.", "Aucune commande ne correspond aux filtres actuels.")
                          : tr("This customer has not placed an order yet.", "Ce client n’a encore passé aucune commande.")
                        }
                      </p>
                      <Button
                        className=""
                        disabled={!capabilities.canOpenSales}
                        onClick={() => {
                          info("Open Sales", `Redirecting to create first order for ${customer.name}`)
                          router.push(localizedHref(`/dashboard/sales`))
                        }}
                      >
                        <Plus className="w-4 h-4 me-2" />
                        {tr("Open sales", "Ouvrir les ventes")}
                      </Button>
                    </div>
                  ) : (
                    <div className="overflow-x-auto">
                      <Table>
                        <TableHeader>
                          <TableRow className="border-[var(--dash-border-subtle)] bg-[var(--dash-surface)]">
                            <TableHead className="font-semibold text-[var(--dash-text-muted)]">
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-auto p-0 hover:bg-transparent font-semibold"
                                onClick={() => handleSort("id")}
                              >
                                {tr("Order", "Commande")}
                                <ArrowUpDown className="ms-2 h-3 w-3" />
                              </Button>
                            </TableHead>
                            <TableHead className="font-semibold text-[var(--dash-text-muted)]">{tr("Status", "Statut")}</TableHead>
                            <TableHead className="font-semibold text-[var(--dash-text-muted)]">
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-auto p-0 hover:bg-transparent font-semibold"
                                onClick={() => handleSort("totalAmount")}
                              >
                                {tr("Total", "Total")}
                                <ArrowUpDown className="ms-2 h-3 w-3" />
                              </Button>
                            </TableHead>
                            <TableHead className="font-semibold text-[var(--dash-text-muted)]">{tr("Items", "Articles")}</TableHead>
                            <TableHead className="font-semibold text-[var(--dash-text-muted)]">
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-auto p-0 hover:bg-transparent font-semibold"
                                onClick={() => handleSort("createdAt")}
                              >
                                {tr("Order date", "Date de commande")}
                                <ArrowUpDown className="ms-2 h-3 w-3" />
                              </Button>
                            </TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {filteredOrders.map((order) => (
                            <TableRow
                              key={order.id}
                              className="group border-[var(--dash-border-subtle)] hover:bg-[var(--dash-brand-soft)] transition-all duration-200"
                            >
                              <TableCell className="py-4">
                                <div className="font-medium text-[var(--dash-text)]">
                                  {order.orderNumber || order.id}
                                </div>
                                <div className="text-sm text-[var(--dash-text-faint)]">
                                  {formatDate(order.createdAt)}
                                </div>
                              </TableCell>
                              <TableCell className="py-4">
                                <Badge className={getStatusColor(order.status.toLowerCase())}>
                                  {getStatusIcon(order.status.toLowerCase())}
                                  <span className="ms-2">{statusLabel(order.status)}</span>
                                </Badge>
                              </TableCell>
                              <TableCell className="py-4">
                                <div className="font-semibold text-[var(--dash-text)]">
                                  {formatCurrency(order.totalAmount)}
                                </div>
                              </TableCell>
                              <TableCell className="py-4">
                                <div className="flex items-center gap-2">
                                  <Package className="h-4 w-4 text-[var(--dash-text-faint)]" />
                                  <span className="text-[var(--dash-text-muted)]">
                                    {order.itemCount} {tr("items", "articles")}
                                  </span>
                                </div>
                              </TableCell>
                              <TableCell className="py-4">
                                <div className="text-sm text-[var(--dash-text-muted)]">
                                  {formatDate(order.createdAt)}
                                </div>
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      </div>
    </TooltipProvider>
  )
}

statusLabel.source:
(status: string) => {
    switch (status.toUpperCase()) {
      case "DRAFT": return tr("Draft", "Brouillon")
      case "CONFIRMED": return tr("Confirmed", "Confirmée")
      case "PROCESSING": return tr("Processing", "En traitement")
      case "SHIPPED": return tr("Shipped", "Expédiée")
      case "DELIVERED": return tr("Delivered", "Livrée")
      case "COMPLETED": return tr("Completed", "Terminée")
      case "CANCELLED": return tr("Cancelled", "Annulée")
      default: return status
    }
  }

handleSort.source:
(field: string) => {
    if (field === sortField) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc")
    } else {
      setSortField(field)
      setSortDirection("desc")
    }
  }

CustomerQuickActions.source:
export function CustomerQuickActions({
  customer,
  capabilities,
  currentPage,
}: CustomerQuickActionsProps) {
  const router = useRouter()
  const pathname = usePathname()
  const locale = getLocaleFromPathname(pathname) ?? DEFAULT_LOCALE
  const t = copy[locale]
  const localizedHref = (href: string) => localizePath(href, locale)
  const { info } = useNotifications()
  const exportMutation = useCustomerExport(locale)

  const navigate = (page: "profile" | "edit" | "orders") => {
    if (currentPage === page) return
    const suffix = page === "profile" ? "" : `/${page}`
    router.push(localizedHref(`/dashboard/customers/${customer.id}${suffix}`))
  }

  const handleContact = (type: "email" | "phone") => {
    const destination = type === "email" ? customer.email : customer.phone
    if (!destination) return

    info(
      type === "email" ? t.contactEmailTitle : t.contactPhoneTitle,
      `${type === "email" ? t.openingEmail : t.openingPhone} ${destination}`,
    )
    window.open(`${type === "email" ? "mailto" : "tel"}:${destination}`)
  }

  return (
    <Card className="dashboard-glass-panel border-[var(--dash-border-subtle)] text-[var(--dash-text)] shadow-sm">
      <CardContent className="space-y-5 p-4">
        <Button
          className="dashboard-button-secondary w-full justify-start rounded-lg"
          onClick={() => router.push(localizedHref("/dashboard/customers"))}
          size="sm"
          variant="outline"
        >
          <ArrowLeft aria-hidden="true" className="me-2 h-4 w-4" />
          {t.back}
        </Button>

        <div className="flex flex-wrap items-center justify-between gap-2">
          <Badge
            className={
              customer.isActive
                ? "border-[var(--dash-success)] bg-[var(--dash-success-soft)] text-[var(--dash-success)]"
                : "border-[var(--dash-border-subtle)] bg-[var(--dash-surface)] text-[var(--dash-text-soft)]"
            }
            variant="outline"
          >
            {customer.isActive ? (
              <CheckCircle2 aria-hidden="true" className="me-1 h-3.5 w-3.5" />
            ) : (
              <XCircle aria-hidden="true" className="me-1 h-3.5 w-3.5" />
            )}
            {customer.isActive ? t.active : t.inactive}
          </Badge>
          {(customer.totalOrders ?? 0) > 0 ? (
            <Badge
              className="border-[var(--dash-border-subtle)] bg-[var(--dash-surface)] text-[var(--dash-text-soft)]"
              variant="outline"
            >
              {customer.totalOrders} {customer.totalOrders === 1 ? t.order : t.orders}
            </Badge>
          ) : null}
        </div>

        <nav aria-label={t.navigation} className="space-y-2">
          <h2 className="text-xs font-black uppercase tracking-[0.14em] text-[var(--dash-text-soft)]">
            {t.navigation}
          </h2>
          <Button
            className="w-full justify-start rounded-lg"
            disabled={currentPage === "profile"}
            onClick={() => navigate("profile")}
            size="sm"
            variant={currentPage === "profile" ? "default" : "outline"}
          >
            <User aria-hidden="true" className="me-2 h-4 w-4" />
            {t.profile}
          </Button>
          {capabilities.canUpdate ? (
            <Button
              className="w-full justify-start rounded-lg"
              disabled={currentPage === "edit"}
              onClick={() => navigate("edit")}
              size="sm"
              variant={currentPage === "edit" ? "default" : "outline"}
            >
              <Edit aria-hidden="true" className="me-2 h-4 w-4" />
              {t.edit}
            </Button>
          ) : null}
          {capabilities.canViewOrders ? (
            <Button
              className="w-full justify-start rounded-lg"
              disabled={currentPage === "orders"}
              onClick={() => navigate("orders")}
              size="sm"
              variant={currentPage === "orders" ? "default" : "outline"}
            >
              <ShoppingCart aria-hidden="true" className="me-2 h-4 w-4" />
              {t.viewOrders}
            </Button>
          ) : null}
        </nav>

        <section aria-labelledby="customer-quick-actions-title" className="space-y-2">
          <h2
            className="text-xs font-black uppercase tracking-[0.14em] text-[var(--dash-text-soft)]"
            id="customer-quick-actions-title"
          >
            {t.quickActions}
          </h2>
          {capabilities.canCreateStatement ? (
            <Button
              className="dashboard-button-secondary w-full justify-start rounded-lg"
              onClick={() => router.push(localizedHref(`/dashboard/customers/${customer.id}/statement`))}
              size="sm"
              variant="outline"
            >
              <ReceiptText aria-hidden="true" className="me-2 h-4 w-4" />
              {t.statement}
            </Button>
          ) : null}
          {capabilities.canOpenSales ? (
            <Button
              className="dashboard-button-secondary w-full justify-start rounded-lg"
              onClick={() => router.push(localizedHref("/dashboard/sales"))}
              size="sm"
              variant="outline"
            >
              <ShoppingCart aria-hidden="true" className="me-2 h-4 w-4" />
              {t.sales}
            </Button>
          ) : null}
          {customer.email ? (
            <Button className="w-full justify-start rounded-lg" onClick={() => handleContact("email")} size="sm" variant="outline">
              <Mail aria-hidden="true" className="me-2 h-4 w-4" />
              {t.email}
            </Button>
          ) : null}
          {customer.phone ? (
            <Button className="w-full justify-start rounded-lg" onClick={() => handleContact("phone")} size="sm" variant="outline">
              <Phone aria-hidden="true" className="me-2 h-4 w-4" />
              {t.call}
            </Button>
          ) : null}
          {capabilities.canExport ? (
            <Button
              className="w-full justify-start rounded-lg"
              disabled={exportMutation.isPending}
              onClick={() => exportMutation.mutate({
                scope: "customer",
                customerId: customer.id,
                purpose: "CUSTOMER_PROFILE_EXPORT",
              })}
              size="sm"
              variant="outline"
            >
              {exportMutation.isPending ? (
                <Loader2 aria-hidden="true" className="me-2 h-4 w-4 animate-spin" />
              ) : (
                <Download aria-hidden="true" className="me-2 h-4 w-4" />
              )}
              {t.export}
            </Button>
          ) : null}
        </section>
      </CardContent>
    </Card>
  )
}

