                  isProfitLossLayout &&
                    "[&>ol]:grid [&>ol]:grid-cols-1 [&>ol]:gap-3 [&>ol]:space-y-0 md:[&>ol]:grid-cols-2 xl:[&>ol]:grid-cols-3",
                )}
