        actorRoleCodes: context.roles.map((role) => role.code),
        isSuperUser: context.isSuperUser,
      })

      return (
        <CashCommandDashboard
          data={data}
          locale={locale}
          title={copy[locale].title}
          subtitle={copy[locale].subtitle}
        />
      )
    },
  })
}

