function buildKpis(result: AROpenItemResult | undefined, t: ARHistoryT, locale: string): TransactionHistoryKpi[] {
  return [
    { id: "items", label: t("kpis.items"), value: result?.summary.itemCount ?? 0, tone: "brand" },
