                          variant="outline"
                          className="shrink-0 rounded-lg border-[var(--dash-border-subtle)] text-[var(--dash-text)]"
                        >
                          <Link href={item.actionLink.href}>
                            <ArrowUpRight
                              className="h-4 w-4"
                              aria-hidden="true"
