                                        />
                                      </TableCell>
                                      <TableCell>
                                        <Input
                                          type="number"
                                          step="0.01"
                                          min="0"
                                          value={line.unitPrice}
                                          onChange={(e) =>
                                            updateOrderLine(line.id, "unitPrice", parseFloat(e.target.value) || 0)
                                          }
                                          className="text-right"
                                        />
                                      </TableCell>
                                      <TableCell>
                                        <Input
                                          type="number"
                                          step="0.01"
                                          min="0"
                                          max="100"
                                          value={line.taxRate}
                                          onChange={(e) =>
                                            updateOrderLine(line.id, "taxRate", parseFloat(e.target.value) || 0)
