                                  />
                                </FormControl>
                                <FormDescription>
                                  Optional notes for the supplier or internal use
                                </FormDescription>
                                <FormMessage />
                              </FormItem>
                            )}
                          />
                        </div>
                      </CardContent>
                    </Card>
                  )}
