                )}

                {po.capabilities.archive.allowed && (
                  <DropdownMenuItem
                    onClick={() => handleDeleteClick(po)}
                    className="text-rose-700 focus:text-rose-700 dark:text-rose-300 dark:focus:text-rose-300"
                  >
