export default async function PurchaseOrderDetailPage({ params, searchParams }: PurchaseOrderDetailPageProps) {
  const { id, locale } = await params
  const { tab } = (await searchParams) ?? {}

  if (!id) {
    notFound()
  }

  const surface = routeByKey("purchase-orders-detail")

  if (!surface) {
    throw new Error("Missing purchase orders route surface definition: purchase-orders-detail")
  }

  return withPurchaseOrdersSurfaceAccess({
    params: Promise.resolve({ locale }),
    surface,
    permissionOptions: {
      resourceId: id,
    },
    onAllowed: async (ctx) => {
      return (
        <ModernPurchaseOrderDetailPage
          id={id}
          organizationId={ctx.orgId}
          requestedAction={tab === "receive" ? "receive" : undefined}
        />
      )
    },
  })
}

