                  <DialogContent className="dashboard-glass-panel rounded-lg border-[var(--dash-border-subtle)] text-[var(--dash-text)]">
                    <DialogHeader>
                      <DialogTitle>Approve Purchase Order</DialogTitle>
                      <DialogDescription>
