export default function SupplierManagementDashboard({
  organizationId,
  locale = "en",
  basePath = "/dashboard/purchases/suppliers",
  createPath = `${basePath}/create`,
  initialAction,
  initialEditId,
  initialAnalyticsId,
  canExport = false,
  canExportSensitive = false,
  canEdit = false,
}: SupplierManagementDashboardProps) {
  const t = copy[locale]
  const notifications = useNotifications()
  const router = useRouter()
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all")
  const [riskFilter, setRiskFilter] = useState<RiskFilter>("all")
  const [formOpen, setFormOpen] = useState(false)
  const archiveOpenerRef = useRef<HTMLButtonElement | null>(null)
  const archiveOpenerSupplierIdRef = useRef<string | null>(null)
  const [editingSupplier, setEditingSupplier] = useState<SupplierManagementRow | null>(null)
  const [archiveTarget, setArchiveTarget] = useState<SupplierManagementRow | null>(null)
  const [requestedSupplierMissing, setRequestedSupplierMissing] = useState(false)
  const [includeSensitiveExport, setIncludeSensitiveExport] = useState(false)
  const [isExporting, setIsExporting] = useState(false)
  const [formState, setFormState] = useState<SupplierFormState>(() => getDefaultForm())
  const [formError, setFormError] = useState<string | null>(null)
  const [initialRequestHandled, setInitialRequestHandled] = useState(false)

  const restoreArchiveOpenerFocus = useCallback(() => {
    const rememberedOpener = archiveOpenerRef.current
    const rememberedSupplierId = archiveOpenerSupplierIdRef.current
    const currentOpener = rememberedOpener?.isConnected
      ? rememberedOpener
      : Array.from(
          document.querySelectorAll<HTMLButtonElement>("[data-supplier-actions-id]"),
        ).find(
          (candidate) =>
            candidate.dataset.supplierActionsId === rememberedSupplierId,
        )
    currentOpener?.focus()

    archiveOpenerRef.current = null
    archiveOpenerSupplierIdRef.current = null
  }, [])

  const {
    data,
    isLoading,
    isFetching,
    isError,
    error,
    refetch,
  } = useSupplierManagementData(organizationId)
  const createMutation = useCreateManagedSupplier(organizationId, locale)
  const updateMutation = useUpdateManagedSupplier(organizationId, locale)
  const archiveMutation = useDeleteManagedSupplier(organizationId, locale)
  const analyticsSupplierId = initialAnalyticsId ?? null
  const analyticsQuery = useSupplierAnalyticsData(organizationId, analyticsSupplierId)

  const suppliers = useMemo(() => data?.suppliers ?? [], [data?.suppliers])
  const isSaving = createMutation.isPending || updateMutation.isPending
  const analyticsSupplier = analyticsQuery.data?.supplier ?? suppliers.find((supplier) => supplier.id === analyticsSupplierId) ?? null
  const invoiceHistoryRows = useMemo(
    () => (analyticsQuery.data?.apHistory.rows ?? []).filter((row) => row.lane === "invoice"),
    [analyticsQuery.data?.apHistory.rows],
  )
  const paymentHistoryRows = useMemo(
    () => (analyticsQuery.data?.apHistory.rows ?? []).filter((row) => row.lane === "payment"),
    [analyticsQuery.data?.apHistory.rows],
  )

  const filteredSuppliers = useMemo(() => {
    return suppliers.filter((supplier) => {
      if (statusFilter === "active" && !supplier.isActive) return false
      if (statusFilter === "inactive" && supplier.isActive) return false
      if (riskFilter === "open-orders" && supplier.openPurchaseOrdersCount === 0) return false
      if (riskFilter === "over-limit" && !isOverCreditLimit(supplier)) return false
      if (riskFilter === "linked-items" && supplier.supplierItemsCount === 0) return false
      if (riskFilter === "no-links" && supplier.supplierItemsCount > 0) return false

      return true
    })
  }, [riskFilter, statusFilter, suppliers])

  const openCreate = useCallback(() => {
    setEditingSupplier(null)
    setRequestedSupplierMissing(false)
    setFormError(null)
    setFormState(getDefaultForm())
    setFormOpen(true)
  }, [])

  const openEdit = useCallback((supplier: SupplierManagementRow) => {
    setEditingSupplier(supplier)
    setRequestedSupplierMissing(false)
    setFormError(null)
    setFormState(formFromSupplier(supplier))
    setFormOpen(true)
  }, [])
  const closeForm = useCallback(() => {
    if (isSaving) return
    setFormOpen(false)
    setEditingSupplier(null)
    setFormError(null)
    setFormState(getDefaultForm())
    if (initialEditId) router.replace(basePath + "/" + initialEditId)
    else if (initialAction) router.replace(basePath)
  }, [basePath, initialAction, initialEditId, isSaving, router])

  useEffect(() => {
    if (initialRequestHandled || isLoading) return

    if (initialAction === "create") {
      openCreate()
      setInitialRequestHandled(true)
      return
    }

    if (initialEditId) {
      const supplier = suppliers.find((item) => item.id === initialEditId)

      if (supplier) {
        openEdit(supplier)
      } else {
        setRequestedSupplierMissing(true)
        setFormOpen(false)
      }

      setInitialRequestHandled(true)
      return
    }

    setInitialRequestHandled(true)
  }, [
    initialAction,
    initialEditId,
    initialRequestHandled,
    isLoading,
    openCreate,
    openEdit,
    suppliers,
  ])

  const updateFormField = useCallback(<K extends keyof SupplierFormState>(field: K, value: SupplierFormState[K]) => {
    setFormState((current) => ({ ...current, [field]: value }))
    setFormError(null)
  }, [])

  const buildInput = useCallback((): SupplierManagementInput | null => {
    const name = formState.name.trim()
    const email = formState.email.trim()
    const paymentTerms = Number(formState.paymentTerms.trim() || 0)
    const creditLimitText = formState.creditLimit.trim()
    const creditLimit = creditLimitText ? Number(creditLimitText) : null

    if (!name) {
      notifications.warning(t.requiredTitle, t.requiredBody)
      setFormError(t.requiredBody)
      return null
    }

    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      notifications.warning(t.invalidEmailTitle, t.invalidEmailBody)
      setFormError(t.invalidEmailBody)
      return null
    }

    if (!Number.isInteger(paymentTerms) || paymentTerms < 0 || paymentTerms > 365) {
      notifications.warning(t.invalidTermsTitle, t.invalidTermsBody)
      setFormError(t.invalidTermsBody)
      return null
    }

    if (creditLimit !== null && (!Number.isFinite(creditLimit) || creditLimit < 0)) {
      notifications.warning(t.invalidCreditTitle, t.invalidCreditBody)
      setFormError(t.invalidCreditBody)
      return null
    }

    return {
      name,
      code: formState.code.trim() || null,
      contactPerson: formState.contactPerson.trim() || null,
      email: email || null,
      phone: formState.phone.trim() || null,
      address: formState.address.trim() || null,
      city: formState.city.trim() || null,
      state: formState.state.trim() || null,
      zipCode: formState.zipCode.trim() || null,
      country: formState.country.trim() || null,
      taxId: formState.taxId.trim() || null,
      paymentTerms,
      creditLimit,
      preferredLocale: formState.preferredLocale,
      notes: formState.notes.trim() || null,
      isActive: formState.isActive,
    }
  }, [formState, notifications, t])

  const submitForm = useCallback(async () => {
    const payload = buildInput()
    if (!payload) return

    try {
      const savedSupplier = editingSupplier
        ? await updateMutation.mutateAsync({ id: editingSupplier.id, data: payload })
        : await createMutation.mutateAsync(payload)

      if ((initialAction || initialEditId) && savedSupplier) {
        router.replace(`${basePath}/${savedSupplier.id}`)
        return
      }

      setFormOpen(false)
      setEditingSupplier(null)
      setFormState(getDefaultForm())
      setFormError(null)
    } catch (mutationError) {
      setFormError(mutationError instanceof Error ? mutationError.message : t.errorTitle)
    }
  }, [
    basePath,
    buildInput,
    createMutation,
    editingSupplier,
    initialAction,
    initialEditId,
    router,
    t.errorTitle,
    updateMutation,
  ])

  const copySupplierId = useCallback(async (supplier: SupplierManagementRow) => {
    try {
      await navigator.clipboard.writeText(buildSupplierClipboardPayload(supplier))
      notifications.success(t.copiedTitle, t.copiedBody)
    } catch {
      notifications.error(t.copyFailedTitle, t.copyFailedBody)
    }
  }, [notifications, t.copiedBody, t.copiedTitle, t.copyFailedBody, t.copyFailedTitle])

  const exportSuppliers = useCallback(async () => {
    if (!canExport || isExporting) return
    setIsExporting(true)

    try {
      const includeSensitiveFields = canExportSensitive && includeSensitiveExport
      const includedFields = buildSupplierExportHeaders(includeSensitiveFields)
      const preparation = await prepareSupplierManagementExport(organizationId, {
        rowCount: filteredSuppliers.length,
        includeSensitiveFields,
        fields: includedFields,
      })
      if (!preparation.success || !preparation.data) {
        throw new Error(preparation.error || "Supplier export could not be prepared")
      }

      const csv = buildSupplierExportCsv(filteredSuppliers, { includeSensitiveFields })
      const blob = new Blob([csv], { type: "text/csv;charset=utf-8" })
      const url = URL.createObjectURL(blob)
      const anchor = document.createElement("a")
      anchor.href = url
      anchor.download = `suppliers-${includeSensitiveFields ? "full" : "redacted"}-${preparation.data.watermarkId}.csv`
      anchor.click()
      URL.revokeObjectURL(url)
      notifications.success(t.exportTitle, t.exportBody)
    } catch (exportError) {
      notifications.error(
        t.errorTitle,
        exportError instanceof Error ? exportError.message : t.errorTitle,
      )
    } finally {
      setIsExporting(false)
    }
  }, [
    canExport,
    canExportSensitive,
    filteredSuppliers,
    includeSensitiveExport,
    isExporting,
    notifications,
    organizationId,
    t.errorTitle,
    t.exportBody,
    t.exportTitle,
  ])

  const columns = useMemo<ColumnDef<SupplierManagementRow>[]>(() => [
    {
      accessorKey: "name",
      header: ({ column }) => (
        <HeaderButton onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}>
          {t.tableColumns.supplier}
          <SortIcon sorted={column.getIsSorted()} />
        </HeaderButton>
      ),
      cell: ({ row }) => {
        const supplier = row.original
        return (
          <div className="flex min-w-[250px] items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg border border-[var(--dash-border-subtle)] bg-[var(--dash-brand-soft)] text-sm font-semibold text-[var(--dash-brand-strong)]">
              {initials(supplier.name)}
            </div>
            <div className="min-w-0">
              <p className="truncate font-semibold text-[var(--dash-text)]">{supplier.name}</p>
              <div className="mt-1 flex min-w-0 flex-wrap items-center gap-1.5">
                <Badge variant="outline" className="rounded-lg border-[var(--dash-border-subtle)] bg-[var(--dash-surface-raised)] font-mono text-[var(--dash-text-soft)]">
                  {supplier.code || t.noCode}
                </Badge>
                <Badge variant="outline" className={cn("rounded-lg", supplier.preferredLocale === "FR" ? toneClass("spruce") : toneClass("brand"))}>
                  <Languages className="me-1 h-3 w-3" />
                  {supplier.preferredLocale}
                </Badge>
              </div>
            </div>
          </div>
        )
      },
      filterFn: (row, _id, value) => {
        const searchValue = String(value).toLowerCase()
        const supplier = row.original
        return [
          supplier.name,
          supplier.code,
          supplier.contactPerson,
          supplier.email,
          supplier.phone,
          supplier.city,
          supplier.country,
          supplier.taxId,
        ]
          .filter(Boolean)
          .some((field) => String(field).toLowerCase().includes(searchValue))
      },
    },
    {
      id: "contact",
      header: t.tableColumns.contact,
      cell: ({ row }) => {
        const supplier = row.original
        return (
          <div className="min-w-[210px] space-y-1.5 text-sm text-[var(--dash-text-soft)]">
            <p className="font-medium text-[var(--dash-text)]">{supplier.contactPerson || t.noContact}</p>
            <p className="flex min-w-0 items-center gap-2">
              <Mail className="h-3.5 w-3.5 shrink-0 text-[var(--dash-info)]" />
              <span className="truncate">{supplier.email || t.noEmail}</span>
            </p>
            <p className="flex min-w-0 items-center gap-2">
              <Phone className="h-3.5 w-3.5 shrink-0 text-[var(--dash-spruce)]" />
              <span className="truncate">{supplier.phone || t.noPhone}</span>
            </p>
          </div>
        )
      },
    },
    {
      id: "commercial",
      header: t.tableColumns.commercial,
      cell: ({ row }) => {
        const supplier = row.original
        const overLimit = isOverCreditLimit(supplier)
        return (
          <div className="min-w-[210px] space-y-2">
            <InlineMetric label={t.creditLimit} value={supplier.creditLimit !== null ? formatCurrency(supplier.creditLimit, locale) : "-"} />
            <InlineMetric label={t.balance} value={formatCurrency(supplier.currentBalance, locale)} tone={overLimit ? "danger" : "default"} />
            <p className="text-xs text-[var(--dash-text-faint)]">
              {supplier.paymentTerms ?? 0} {t.days}
            </p>
          </div>
        )
      },
    },
    {
      id: "activity",
      header: t.tableColumns.activity,
      cell: ({ row }) => {
        const supplier = row.original
        return (
          <div className="grid min-w-[230px] grid-cols-2 gap-2 text-sm">
            <InlineMetric label={t.linkedItemsCard} value={formatNumber(supplier.supplierItemsCount, locale)} />
            <InlineMetric label={t.openOrdersCard} value={formatNumber(supplier.openPurchaseOrdersCount, locale)} tone={supplier.openPurchaseOrdersCount > 0 ? "gold" : "default"} />
            <InlineMetric label={t.totalPurchases} value={formatCurrency(supplier.totalPurchaseValue, locale)} />
            <InlineMetric label={t.preferredLinks} value={formatNumber(supplier.preferredItemsCount, locale)} />
          </div>
        )
      },
    },
    {
      accessorKey: "isActive",
      header: ({ column }) => (
        <HeaderButton onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}>
          {t.tableColumns.status}
          <SortIcon sorted={column.getIsSorted()} />
        </HeaderButton>
      ),
      cell: ({ row }) => {
        const supplier = row.original
        const overLimit = isOverCreditLimit(supplier)
        return (
          <div className="space-y-2">
            <Badge variant="outline" className={cn("rounded-lg", supplier.isActive ? toneClass("spruce") : toneClass("muted"))}>
              {supplier.isActive ? <CheckCircle2 className="me-1 h-3.5 w-3.5" /> : <XCircle className="me-1 h-3.5 w-3.5" />}
              {supplier.isActive ? t.active : t.inactive}
            </Badge>
            {overLimit ? (
              <Badge variant="outline" className={cn("rounded-lg", toneClass("danger"))}>
                <ShieldAlert className="me-1 h-3.5 w-3.5" />
                {t.overLimit}
              </Badge>
            ) : null}
          </div>
        )
      },
    },
    {
      accessorKey: "updatedAt",
      header: ({ column }) => (
        <HeaderButton onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}>
          {t.tableColumns.updated}
          <SortIcon sorted={column.getIsSorted()} />
        </HeaderButton>
      ),
      cell: ({ row }) => (
        <div className="min-w-[150px] text-sm text-[var(--dash-text-soft)]">
          {formatDate(row.original.updatedAt, locale)}
        </div>
      ),
    },
    {
      id: "actions",
      header: t.tableColumns.actions,
      enableSorting: false,
      enableHiding: false,
      cell: ({ row }) => {
        const supplier = row.original
        return (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                data-supplier-actions-id={supplier.id}
                onClick={(event) => {
                  archiveOpenerRef.current = event.currentTarget
                  archiveOpenerSupplierIdRef.current = supplier.id
                }}
                className="h-9 w-9 rounded-lg text-[var(--dash-text-soft)] hover:bg-[var(--dash-brand-soft)] hover:text-[var(--dash-brand-strong)]"
              >
                <MoreHorizontal className="h-4 w-4" />
                <span className="sr-only">Open supplier actions</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-52 border-[var(--dash-border-subtle)] bg-[var(--dash-surface-raised)] text-[var(--dash-text)]">
              <DropdownMenuLabel>{t.actions}</DropdownMenuLabel>
              <DropdownMenuItem onClick={() => copySupplierId(supplier)}>
                <Copy className="me-2 h-4 w-4" />
                {t.copyId}
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem asChild>
                <Link href={`${basePath}/${supplier.id}`}>
                  <BarChart3 className="me-2 h-4 w-4" />
                  {t.viewAnalytics}
                </Link>
              </DropdownMenuItem>
              {canEdit ? (
                <DropdownMenuItem asChild>
                  <Link href={`${basePath}/${supplier.id}/edit`}>
                    <Edit3 className="me-2 h-4 w-4" />
                    {t.editSupplier}
                  </Link>
                </DropdownMenuItem>
              ) : null}
              <DropdownMenuSeparator />
              <DropdownMenuItem
                className="text-[var(--dash-danger)] focus:text-[var(--dash-danger)]"
                onClick={() => {
                  archiveOpenerSupplierIdRef.current = supplier.id
                  archiveOpenerRef.current = Array.from(
                    document.querySelectorAll<HTMLButtonElement>(
                      "[data-supplier-actions-id]",
                    ),
                  ).find(
                    (candidate) =>
                      candidate.dataset.supplierActionsId === supplier.id,
                  ) ?? null
                  setArchiveTarget(supplier)
                }}
              >
                <Archive className="me-2 h-4 w-4" />
                {t.archive}
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        )
      },
    },
  ], [basePath, canEdit, copySupplierId, locale, t])

  const statsCards = useMemo(() => {
    const summary = data?.summary
    return [
      {
        label: t.totalSuppliers,
        value: formatNumber(summary?.totalSuppliers ?? 0, locale),
        Icon: Truck,
        accent: "var(--dash-brand)",
        soft: "var(--dash-brand-soft)",
        sub: t.suppliers,
      },
      {
        label: t.activeSuppliers,
        value: formatNumber(summary?.activeSuppliers ?? 0, locale),
        Icon: CheckCircle2,
        accent: "var(--dash-success)",
        soft: "var(--dash-success-soft)",
        sub: `${formatNumber(summary?.inactiveSuppliers ?? 0, locale)} ${t.inactive}`,
      },
      {
        label: t.linkedItemsCard,
        value: formatNumber(summary?.linkedItems ?? 0, locale),
        Icon: PackageCheck,
        accent: "var(--dash-info)",
        soft: "var(--dash-info-soft)",
        sub: `${formatNumber(summary?.preferredItemLinks ?? 0, locale)} ${t.preferredLinks}`,
      },
      {
        label: t.openOrdersCard,
        value: formatNumber(summary?.openPurchaseOrders ?? 0, locale),
        Icon: ShoppingCart,
        accent: "var(--dash-gold)",
        soft: "var(--dash-gold-soft)",
        sub: `${formatNumber(summary?.purchaseOrders ?? 0, locale)} ${t.totalPurchases}`,
      },
      {
        label: t.creditLimit,
        value: formatCurrency(summary?.totalCreditLimit ?? 0, locale),
        Icon: Wallet,
        accent: "var(--dash-spruce)",
        soft: "var(--dash-spruce-soft)",
        sub: `${formatNumber(summary?.averagePaymentTerms ?? 0, locale)} ${t.days}`,
      },
      {
        label: t.balance,
        value: formatCurrency(summary?.totalBalance ?? 0, locale),
        Icon: ShieldAlert,
        accent: "var(--dash-warm)",
        soft: "var(--dash-warm-soft)",
        sub: `${formatNumber(summary?.overCreditLimitSuppliers ?? 0, locale)} ${t.overLimit}`,
      },
    ]
  }, [data?.summary, locale, t])

  const isDirectFormRoute = Boolean(initialAction || initialEditId)
  const isDirectDetailRoute = Boolean(initialAnalyticsId)
  const routeEditingSupplier =
    editingSupplier ??
    (initialEditId
      ? suppliers.find((supplier) => supplier.id === initialEditId) ?? null
      : null)
  const routeDetailSupplier =
    analyticsSupplier ??
    (initialAnalyticsId
      ? suppliers.find((supplier) => supplier.id === initialAnalyticsId) ?? null
      : null)
  const apCompleteness = analyticsQuery.data?.apHistory.completeness.state
  const apRecordedThrough =
    analyticsQuery.data?.apHistory.snapshot.recordedThrough ?? null

  if (isLoading) {
    return (
      <section className="dashboard-glass-panel flex min-h-[24rem] items-center justify-center rounded-lg border border-[var(--dash-border-subtle)] p-8 text-center">
        <div className="space-y-4">
          <Loader2 className="mx-auto h-8 w-8 animate-spin text-[var(--dash-brand-strong)]" />
          <div>
            <p className="font-semibold text-[var(--dash-text)]">{t.loadingTitle}</p>
            <p className="mt-1 text-sm text-[var(--dash-text-soft)]">{t.loadingBody}</p>
          </div>
        </div>
      </section>
    )
  }

  if (isError) {
    return (
      <section className="dashboard-glass-panel flex min-h-[24rem] items-center justify-center rounded-lg border border-[var(--dash-border-subtle)] p-8 text-center">
        <div className="max-w-md space-y-4">
          <AlertCircle className="mx-auto h-9 w-9 text-[var(--dash-danger)]" />
          <div>
            <p className="font-semibold text-[var(--dash-text)]">{t.errorTitle}</p>
            <p className="mt-1 text-sm text-[var(--dash-text-soft)]">
              {error instanceof Error ? error.message : t.errorTitle}
            </p>
          </div>
          <Button type="button" onClick={() => refetch()} className="dashboard-button-primary h-10 rounded-lg">
            <RefreshCw className="h-4 w-4" />
            {t.retry}
          </Button>
        </div>
      </section>
    )
  }

  return (
    <>
      {isDirectFormRoute ? (
        <section
          className="space-y-4"
          data-supplier-presentation={
            initialEditId ? "edit-page" : "create-page"
          }
        >
          <CommandBriefHeader
            eyebrow={t.purchasingContext}
            title={
              initialEditId
                ? routeEditingSupplier?.name ?? t.edit
                : t.create
            }
            summary={initialEditId ? t.editSummary : t.createSummary}
            state={{
              label: routeEditingSupplier
                ? routeEditingSupplier.isActive
                  ? t.active
                  : t.inactive
                : t.purchasingReady,
              tone: routeEditingSupplier
                ? routeEditingSupplier.isActive
                  ? "spruce"
                  : "muted"
                : "info",
              icon: routeEditingSupplier?.isActive
                ? CheckCircle2
                : routeEditingSupplier
                  ? XCircle
                  : Truck,
            }}
            metadata={
              routeEditingSupplier
                ? [
                    {
                      label: t.fields.code,
                      value: routeEditingSupplier.code || t.noCode,
                      icon: Building2,
                    },
                    {
                      label: t.recordUpdated,
                      value: formatDate(routeEditingSupplier.updatedAt, locale),
                      icon: CalendarClock,
                    },
                  ]
                : [
                    {
                      label: t.supplierRecord,
                      value: t.formDescription,
                      icon: Truck,
                    },
                  ]
            }
            actions={[
              {
                label: initialEditId
                  ? t.backToSupplier
                  : t.backToSuppliers,
                href: initialEditId
                  ? basePath + "/" + initialEditId
                  : basePath,
                icon: ArrowLeft,
                variant: "secondary",
              },
            ]}
          />
        </section>
      ) : isDirectDetailRoute ? (
        <section
          className="space-y-4"
          data-supplier-presentation="detail-page"
        >
          <CommandBriefHeader
            eyebrow={t.supplierRecord}
            title={routeDetailSupplier?.name ?? t.analytics}
            summary={t.detailSummary}
            state={{
              label: routeDetailSupplier?.isActive ? t.active : t.inactive,
              tone: routeDetailSupplier?.isActive ? "spruce" : "muted",
              icon: routeDetailSupplier?.isActive ? CheckCircle2 : XCircle,
            }}
            metadata={[
              {
                label: t.fields.code,
                value: routeDetailSupplier?.code || t.noCode,
                icon: Building2,
              },
              {
                label: t.recordUpdated,
                value: routeDetailSupplier
                  ? formatDate(routeDetailSupplier.updatedAt, locale)
                  : "-",
                icon: CalendarClock,
              },
            ]}
            actions={[
              {
                label: t.backToSuppliers,
                href: basePath,
                icon: ArrowLeft,
                variant: "secondary",
              },
              ...(canEdit && initialAnalyticsId
                ? [
                    {
                      label: t.editSupplier,
                      href: basePath + "/" + initialAnalyticsId + "/edit",
                      icon: Edit3,
                      variant: "primary" as const,
                    },
                  ]
                : []),
              ...(initialAnalyticsId
                ? [
                    {
                      label: t.invoiceHistory,
                      href:
                        "/" +
                        locale +
                        "/dashboard/purchases/payables/history?supplierId=" +
                        encodeURIComponent(initialAnalyticsId),
                      icon: CalendarClock,
                      variant: "secondary" as const,
                    },
                  ]
                : []),
            ]}
            proof={{
              state:
                apCompleteness === "partial" ? "pending" : "operational",
              label:
                apCompleteness === "partial"
                  ? t.partialHistory
                  : t.completeHistory,
              source: apRecordedThrough
                ? formatDate(apRecordedThrough, locale)
                : t.apProof,
            }}
          />

          {analyticsQuery.data && routeDetailSupplier ? (
            <StatusStrip
              title={t.supplierRecord}
              detail={t.detailSummary}
              items={[
                {
                  id: "lifecycle",
                  label: t.status,
                  value: routeDetailSupplier.isActive
                    ? t.active
                    : t.inactive,
                  tone: routeDetailSupplier.isActive ? "spruce" : "muted",
