                {t.copyId}
              </DropdownMenuItem>
              {organization.id === organizationId ? (
                <>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem asChild>
                    <Link href={dashboardPath("settings", "users")} locale={locale}>
                      <Users className="h-4 w-4" />
                      {t.openUsers}
                      <ExternalLink className="ms-auto h-3 w-3" />
