                      {t.openRoles}
                      <ExternalLink className="ms-auto h-3 w-3" />
                    </Link>
                  </DropdownMenuItem>
                  <DropdownMenuItem asChild>
                    <Link href={dashboardPath("inventory", "items")} locale={locale}>
                      <Package className="h-4 w-4" />
