}

MiniBadge.source:
function MiniBadge({
  label,
  value,
  locale,
}: {
  label: string
  value: number
  locale: Locale
}) {
  return (
    <Badge variant="outline" className="rounded-lg border-[var(--dash-border-subtle)] bg-[rgba(37,57,67,0.34)] text-[var(--dash-text-soft)]">
      {label}: {formatNumber(value, locale)}
