      action: SecurityEventType.AUTH_PASSWORD_RESET_COMPLETED,
      changes: { sessionsRevoked: true, resetLinkConsumed: true },
    } })
    return true
  }, { isolationLevel: "ReadCommitted", timeout: 10000 }).catch

