  onAllowed: (context: CustomersRouteContext, locale: Locale) => Promise<ReactNode> | ReactNode
}) {
  const state = await evaluateCustomersRouteAccess(surface, params, permissionOptions)

  if (state.kind === "blocked") {
    return state.node
  }

  return onAllowed(state.context, state.locale)
}

