  }

  return row
}

removeCustomerWithRetention.source:
async function removeCustomerWithRetention(
  organizationId: string,
  customerId: string,
): Promise<{ customer: CustomerDTO; mode: CustomerRemovalReceipt["mode"] }> {
  const customer = await db.customer.findFirst({
    where: { id: customerId, organizationId, deletedAt: null },
    select: {
      id: true,
      _count: {
        select: {
          salesOrders: true,
          ledgerEntries: true,
          receivableDocuments: true,
          statementSnapshots: true,
          settlements: true,
        },
      },
    },
  })

  if (!customer) {
    throw new NotFoundError("Customer not found")
  }

  const hasHistory =
    customer._count.salesOrders > 0 ||
    customer._count.ledgerEntries > 0 ||
    customer._count.receivableDocuments > 0 ||
    customer._count.statementSnapshots > 0 ||
    customer._count.settlements > 0

  const updated = await db.customer.update({
    where: { id: customerId },
    data: hasHistory
      ? { isActive: false }
      : { isActive: false, deletedAt: new Date() },
  })

  return { customer: updated, mode: hasHistory ? "deactivated" : "archived" }
}

