export async function deleteCustomerAction(id: string): Promise<ServerActionResult<CustomerRemovalResult>> {
  try {
    if (!id) {
      throw new BusinessRuleError("Customer ID is required")
    }

    const result = await deleteCustomer(id)
    const receipt = assertSuccess(result)
    try {
      revalidateCustomerPaths(id)
      return { success: true, data: { ...receipt, cacheStatus: "invalidated" } }
    } catch {
      return { success: true, data: { ...receipt, cacheStatus: "deferred" } }
    }
  } catch (error) {
    return safeServerActionErrorResult<CustomerRemovalResult>(error, { action: "deleteCustomerAction" })
  }
}

getCustomerOrdersAction.source:
export async function getCustomerOrdersAction(customerId: string): Promise<ServerActionResult<CustomerOrdersResult>> {
  try {
    if (!customerId || customerId.trim().length === 0) {
      throw new BusinessRuleError("Invalid customer ID provided")
    }

    const orders = assertSuccess(await getCustomerOrders(customerId))
    const totalOrders = orders.length
    const totalRevenue = orders.reduce((sum, order) => sum + order.totalAmount, 0)
    const deliveredOrders = orders.filter(
      (order) => order.status === "DELIVERED" || order.status === "COMPLETED",
    ).length

    return {
      success: true,
      data: {
        orders,
        stats: {
          totalOrders,
          totalRevenue,
          averageOrderValue: totalOrders > 0 ? totalRevenue / totalOrders : 0,
          deliveredOrders,
        },
      },
    }
  } catch (error) {
    return safeServerActionErrorResult<CustomerOrdersResult>(error, { action: "getCustomerOrdersAction" })
  }
}

