}

isDateInRange.source:
function isDateInRange(
  value: Date | string | null | undefined,
  start: Date,
  end: Date,
) {
  if (!value) return false
  const date = value instanceof Date ? value : new Date(value)
  return !Number.isNaN(date.getTime()) && date >= start && date <= end
}

minDateString.source:
function minDateString(values: Array<Date | string | null | undefined>) {
  let earliest: Date | null = null
  for (const value of values) {
    if (!value) continue
    const date = value instanceof Date ? value : new Date(value)
    if (Number.isNaN(date.getTime())) continue
    if (!earliest || date < earliest) earliest = date
  }
  return earliest?.toISOString() ?? null
}

addUtcDays.source:
function addUtcDays(date: Date, days: number) {
  const next = new Date(date)
  next.setUTCDate(next.getUTCDate() + days)
  return next
}

startOfUtcDay.source:
function startOfUtcDay(date: Date) {
  const next = new Date(date)
  next.setUTCHours(0, 0, 0, 0)
  return next
}

endOfUtcDay.source:
function endOfUtcDay(date: Date) {
  const next = startOfUtcDay(date)
  next.setUTCDate(next.getUTCDate() + 1)
  next.setUTCMilliseconds(next.getUTCMilliseconds() - 1)
  return next
}

