function sumBy<T>(rows: T[], selector: (row: T) => number) {
  return rows.reduce((total, row) => total + selector(row), 0)
}

startOfDay.source:
function startOfDay(date: Date) {
  const next = new Date(date)
  next.setHours(0, 0, 0, 0)
  return next
}

endOfDay.source:
function endOfDay(date: Date) {
  const next = new Date(date)
  next.setHours(23, 59, 59, 999)
  return next
}

startOfMonth.source:
function startOfMonth(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), 1)
}

startOfQuarter.source:
function startOfQuarter(date: Date) {
  return new Date(date.getFullYear(), Math.floor(date.getMonth() / 3) * 3, 1)
}

startOfYear.source:
function startOfYear(date: Date) {
  return new Date(date.getFullYear(), 0, 1)
}

resolveDateRange.source:
function resolveDateRange(
  period: FinanceDashboardPeriod,
  startDate?: Date,
  endDate?: Date,
) {
  const now = new Date()

  if (period === "custom") {
    return {
      startDate: startDate ? startOfDay(startDate) : startOfDay(now),
      endDate: endDate ? endOfDay(endDate) : endOfDay(now),
    }
  }

  if (period === "yesterday") {
    const yesterday = new Date(now.getTime() - dayMs)
    return { startDate: startOfDay(yesterday), endDate: endOfDay(yesterday) }
  }

  if (period === "7d") {
    return {
      startDate: startOfDay(new Date(now.getTime() - 6 * dayMs)),
      endDate: endOfDay(now),
    }
  }

  if (period === "30d") {
    return {
      startDate: startOfDay(new Date(now.getTime() - 29 * dayMs)),
      endDate: endOfDay(now),
    }
  }

  if (period === "qtd") {
    return {
      startDate: startOfDay(startOfQuarter(now)),
      endDate: endOfDay(now),
    }
  }

  if (period === "ytd") {
    return { startDate: startOfDay(startOfYear(now)), endDate: endOfDay(now) }
  }

  if (period === "today") {
    return { startDate: startOfDay(now), endDate: endOfDay(now) }
  }

  return { startDate: startOfDay(startOfMonth(now)), endDate: endOfDay(now) }
}

