ageBucket.source:
function ageBucket(date: Date, now: Date) {
  const days = Math.max(0, Math.floor((now.getTime() - date.getTime()) / dayMs))
  if (days <= 30) return "current"
  if (days <= 60) return "d31"
  if (days <= 90) return "d61"
  return "d90"
}

