    db.salesOrder.findMany({
      where: {
        organizationId: input.organizationId,
        deletedAt: null,
        paymentStatus: { in: ["PENDING", "PARTIAL"] },
        status: { notIn: ["DRAFT", "CANCELLED"] },
        ...locationCondition,
