export async function updateLegacyLocationByIdForOrg(
  organizationId: string,
  locationId: string,
  input: LocationDTO,
): Promise<LocationDTO> {
  const location = await db.$transaction(async (tx) => {
    const existingLocation = await tx.location.findFirst({
      where: { id: locationId, organizationId, deletedAt: null },
      select: { id: true },
    })

    if (!existingLocation) {
      throw new NotFoundError("Location not found")
    }

    const managerId = input.managerId !== undefined
      ? await assertManagerBelongsToOrg(organizationId, input.managerId, tx)
      : undefined

    return tx.location.update({
      where: { id: locationId },
      data: {
        ...(input.name !== undefined ? { name: input.name } : {}),
        ...(input.code !== undefined ? { code: input.code } : {}),
        ...(input.type !== undefined ? { type: toLocationType(input.type) } : {}),
        ...(input.address !== undefined ? { address: input.address } : {}),
        ...(input.phone !== undefined ? { phone: input.phone } : {}),
        ...(input.email !== undefined ? { email: input.email } : {}),
        ...(input.isActive !== undefined ? { isActive: input.isActive } : {}),
        ...(input.isDefault !== undefined ? { isDefault: input.isDefault } : {}),
        ...(managerId !== undefined ? { managerId } : {}),
        ...(input.allowNegativeStock !== undefined ? { allowNegativeStock: input.allowNegativeStock } : {}),
        ...(input.requiresApproval !== undefined ? { requiresApproval: input.requiresApproval } : {}),
        updatedAt: new Date(),
      },
    })
  })

  return location as unknown as LocationDTO
}

archiveLocationForManagement.source:
export async function archiveLocationForManagement(
  organizationId: string,
  locationId: string,
): Promise<{ id: string }> {
  const location = await db.location.findFirst({
    where: { id: locationId, organizationId, deletedAt: null },
    select: {
      id: true,
      _count: {
        select: {
          inventoryLevels: true,
          posSessions: true,
          salesOrders: true,
          purchaseOrders: true,
        },
      },
    },
  })

  if (!location) {
    throw new NotFoundError("Location not found")
  }

  if (
    location._count.inventoryLevels > 0 ||
    location._count.posSessions > 0 ||
    location._count.salesOrders > 0 ||
    location._count.purchaseOrders > 0
  ) {
    throw new BusinessRuleError("This location has operational history. Deactivate it instead of archiving.")
  }

  await db.location.update({
    where: { id: locationId },
    data: {
      isActive: false,
      isDefault: false,
      deletedAt: new Date(),
      updatedAt: new Date(),
    },
  })

  return { id: locationId }
}

resolveActionOrganization.source:
export async function resolveActionOrganization(explicitOrgId?: string | null, resourceName = "resources") {
  const { orgId } = await requireOrg()
  const requestedOrgId = explicitOrgId?.trim()

  if (!requestedOrgId || requestedOrgId === orgId) {
    return orgId
  }

  throw new ForbiddenError(`You cannot access ${resourceName} for another organization`)
}

