getUnitManagementDataForOrg.source:
export async function getUnitManagementDataForOrg(
  organizationId: string,
): Promise<UnitManagementData> {
  const units = await db.unit.findMany({
    where: { organizationId },
    orderBy: [
      { isActive: "desc" },
      { type: "asc" },
      { nameEn: "asc" },
    ],
    select: {
      id: true,
      organizationId: true,
      nameEn: true,
      nameFr: true,
      symbol: true,
      type: true,
      baseUnit: true,
      conversionRate: true,
      isActive: true,
      createdAt: true,
      updatedAt: true,
      organization: {
        select: { name: true },
      },
      _count: {
        select: { items: true },
      },
    },
  })

  const unitIds = units.map((unit) => unit.id)
  const activeItemCounts = unitIds.length
    ? await db.item.groupBy({
        by: ["unitId"],
        where: {
          organizationId,
          unitId: { in: unitIds },
          deletedAt: null,
          isActive: true,
        },
        _count: { _all: true },
      })
    : []

  const activeItemsByUnitId = new Map<string, number>()
  activeItemCounts.forEach((summary) => {
    if (summary.unitId) {
      activeItemsByUnitId.set(summary.unitId, summary._count._all)
    }
  })

  return {
    units: units.map((unit) => ({
      id: unit.id,
      organizationId: unit.organizationId,
      organizationName: unit.organization.name,
      name: unit.nameEn,
      nameEn: unit.nameEn,
      nameFr: unit.nameFr,
      symbol: unit.symbol,
      type: unit.type,
      baseUnit: unit.baseUnit,
      conversionRate: unit.conversionRate ? unit.conversionRate.toString() : null,
      isActive: unit.isActive,
      createdAt: unit.createdAt,
      updatedAt: unit.updatedAt,
      itemsCount: unit._count.items,
      activeItemsCount: activeItemsByUnitId.get(unit.id) ?? 0,
    })),
  }
}

