export function validateItemStockRange(
  data: { minStockLevel: number; maxStockLevel?: number | null },
  ctx: RefinementCtx,
) {
  if (
    data.maxStockLevel !== null &&
    data.maxStockLevel !== undefined &&
    data.maxStockLevel < data.minStockLevel
