        unitCost: line.unitCost,
        movementType: TransactionType.SALES_RETURN,
        referenceType: TransactionReferenceType.SALES_ORDER,
        referenceId: input.saleId,
        referenceNumber: input.orderNumber,
        notes: line.notes ?? input.reason,
      })),
    },
    client,
  )
}

