export async function listSuppliersForPicker(
  orgId: string,
  input: SupplierPickerListInput = {},
): Promise<SupplierPickerListResult> {
  const page = Math.max(1, Number(input.page ?? 1))
  const pageSize = Math.min(200, Math.max(1, Number(input.pageSize ?? 20)))
  const skip = (page - 1) * pageSize
  const search = input.search?.trim()

  const where: Prisma.SupplierWhereInput = {
    organizationId: orgId,
    deletedAt: null,
    ...(typeof input.isActive === "boolean" ? { isActive: input.isActive } : {}),
    ...(search
      ? {
          OR: [
            { name: { contains: search, mode: "insensitive" } },
            { code: { contains: search, mode: "insensitive" } },
            { contactPerson: { contains: search, mode: "insensitive" } },
            { email: { contains: search, mode: "insensitive" } },
            { phone: { contains: search, mode: "insensitive" } },
          ],
        }
      : {}),
  }

  const [suppliers, total] = await Promise.all([
    db.supplier.findMany({
      where,
      orderBy: { name: "asc" },
      skip,
      take: pageSize,
      select: {
        id: true,
        name: true,
        code: true,
        contactPerson: true,
        email: true,
        phone: true,
        address: true,
        city: true,
        state: true,
        zipCode: true,
        country: true,
        taxId: true,
        paymentTerms: true,
        creditLimit: true,
        notes: true,
        isActive: true,
        currentBalance: true,
        createdAt: true,
        updatedAt: true,
      },
    }),
    db.supplier.count({ where }),
  ])

  return {
    data: suppliers.map((supplier) => ({
      ...supplier,
      creditLimit: supplier.creditLimit !== null ? toNumber(supplier.creditLimit) : null,
      currentBalance: toNumber(supplier.currentBalance),
    })),
    total,
    page,
    pageSize,
    totalPages: Math.max(1, Math.ceil(total / pageSize)),
  }
}

