export async function searchSuppliersLite(
  orgId: string,
  params: SupplierSearchParams,
): Promise<Array<Pick<Supplier, "id" | "name" | "code" | "email">>> {
  const { q, limit } = params
  const where: Prisma.SupplierWhereInput = {
