        console.error("Failed to fetch organization locations:", error)
        notifyError(
          "Failed to Load Locations",
          "Unable to load locations for this organization. Please try again.",
          {
            category: "error",
            priority: "normal",
            action: {
              label: "Retry",
              onClick: () => console.log("Retry locations fetch")
            }
