hasTransaction.source:
function hasTransaction(client: DbClient): client is typeof db {
  return typeof (client as typeof db).$transaction === "function";
}

inTransaction.source:
async function inTransaction<T>(
  client: DbClient,
  work: (tx: Prisma.TransactionClient) => Promise<T>,
) {
  if (hasTransaction(client)) return client.$transaction((tx) => work(tx));
  return work(client as Prisma.TransactionClient);
}

safeJson.source:
function safeJson(value: unknown): Prisma.InputJsonValue {
  return JSON.parse(JSON.stringify(value ?? null)) as Prisma.InputJsonValue;
}

asRecord.source:
function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

metadataString.source:
function metadataString(value: unknown, key: string) {
  const entry = asRecord(value)[key];
  return typeof entry === "string" && entry.trim().length > 0
    ? entry.trim()
    : null;
}

metadataStringList.source:
function metadataStringList(value: unknown, key: string) {
  const entry = asRecord(value)[key];
  return Array.isArray(entry)
    ? entry.filter((item): item is string => typeof item === "string" && item.trim().length > 0)
    : [];
}

paymentBatchProofMetadata.source:
function paymentBatchProofMetadata(batch: PayrollPaymentBatchRecord) {
  const metadata = asRecord(batch.metadata);
  const componentRegisterProofHash = metadataString(
    metadata,
    "componentRegisterProofHash",
  );
  const componentRegisterProofStatus = metadataString(
    metadata,
    "componentRegisterProofStatus",
  );
  const payrollComponentMappingHash = metadataString(
    metadata,
    "payrollComponentMappingHash",
  );
  const payrollComponentMappingStatus = metadataString(
    metadata,
    "payrollComponentMappingStatus",
  );
  const paymentAdapterProofHash = metadataString(
    metadata,
    "paymentAdapterProofHash",
  );
  const paymentAdapterRegistryVersion =
    typeof metadata.paymentAdapterRegistryVersion === "number"
      ? metadata.paymentAdapterRegistryVersion
      : null;
  const paymentProviderAdapterContractHash = metadataString(
    metadata,
    "paymentProviderAdapterContractHash",
  );
  const paymentAdapterStatus = metadataString(metadata, "paymentAdapterStatus");
  const yearToDatePolicy = asRecord(metadata.yearToDatePolicy);
  const yearToDatePolicyHash =
    metadataString(metadata, "yearToDatePolicyHash") ??
    metadataString(yearToDatePolicy, "ytdPolicyHash");
  const yearToDateAccumulatorHashes = metadataStringList(
    metadata,
    "yearToDateAccumulatorHashes",
  ).sort();
  const paymentProviderAdapterKey = metadataString(
    metadata,
    "paymentProviderAdapterKey",
  );
  const adapterChaosReleaseGateHash = metadataString(
    metadata,
    "adapterChaosReleaseGateHash",
  );
  const productionPaymentAutomationSupported =
    metadata.productionPaymentAutomationSupported === true;

  if (
    !componentRegisterProofHash ||
    componentRegisterProofStatus !== "MATCHED"
  ) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires matched statutory component register proof from the released payment batch.",
    );
  }
  if (!payrollComponentMappingHash || !payrollComponentMappingStatus) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires payroll component mapping proof from the released payment batch.",
    );
  }
  if (
    !paymentAdapterProofHash ||
    paymentAdapterRegistryVersion === null ||
    !paymentProviderAdapterContractHash ||
    !paymentAdapterStatus ||
    !paymentProviderAdapterKey
  ) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires provider adapter proof from the released payment batch.",
    );
  }
  if (productionPaymentAutomationSupported && !adapterChaosReleaseGateHash) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires adapter chaos release gate proof from the released payment batch.",
    );
  }

  return {
    componentRegisterProofHash,
    componentRegisterProofStatus,
    payrollComponentMappingHash,
    payrollComponentMappingStatus,
    yearToDatePolicy,
    yearToDatePolicyHash,
    yearToDateAccumulatorHashes,
    paymentAdapterProofHash,
    paymentAdapterRegistryVersion,
    paymentProviderAdapterContractHash,
    paymentAdapterStatus,
    paymentProviderAdapterKey,
    adapterChaosReleaseGateHash: adapterChaosReleaseGateHash ?? null,
    providerSettlementProofRequired:
      metadata.providerSettlementProofRequired === true,
    productionPaymentAutomationSupported,
  };
}

parseDate.source:
function parseDate(value: Date | string | number | undefined, fallback: Date) {
  if (value instanceof Date && !Number.isNaN(value.getTime())) return value;
  if (typeof value === "string" || typeof value === "number") {
    const parsed = new Date(value);
    if (!Number.isNaN(parsed.getTime())) return parsed;
  }
  return fallback;
}

decimal.source:
function decimal(value: Prisma.Decimal.Value | null | undefined) {
  return new Prisma.Decimal(value ?? 0).toDecimalPlaces(2);
}

decimalString.source:
function decimalString(value: Prisma.Decimal.Value | null | undefined) {
  return decimal(value).toFixed(2);
}

amount.source:
function amount(
  decision: RedactionDecision,
  value: Prisma.Decimal.Value | null | undefined,
) {
  return decision.allowed ? decimalString(value) : decision.replacement;
}

redactText.source:
function redactText(
  decision: RedactionDecision,
  value: string | null | undefined,
) {
  if (!value) return null;
  return decision.allowed ? value : decision.replacement;
}

proofIdentifier.source:
function proofIdentifier(
  decision: RedactionDecision,
  value: string | null | undefined,
) {
  if (!value) return null;
  return decision.allowed ? value : decision.replacement;
