loadReconciliationRows.source:
async function loadReconciliationRows(
  client: Prisma.TransactionClient,
  input: z.output<typeof payrollPaymentReconciliationInputSchema>,
) {
  const batches = await client.payrollPaymentBatch.findMany({
    where: {
      organizationId: input.organizationId,
      ...(input.payrollRunId ? { payrollRunId: input.payrollRunId } : {}),
      ...(input.payrollPaymentBatchId
        ? { id: input.payrollPaymentBatchId }
        : {}),
    },
    include: payrollPaymentBatchInclude,
    orderBy: [{ paymentDate: "desc" }, { createdAt: "desc" }],
    take: input.limit,
  });

  if (input.payrollPaymentBatchId && batches.length === 0) {
    throw new NotFoundError("Payroll payment batch not found.");
  }

  const batchIds = batches.map((batch) => batch.id);
  const transactionIds = batches
    .map((batch) => batch.paymentTransactionId)
    .filter((id): id is string => Boolean(id));

  const [transactions, exceptions, matches, suspenseItems, inboxItems] =
    batchIds.length
      ? await Promise.all([
          client.paymentTransaction.findMany({
            where: {
              organizationId: input.organizationId,
              OR: [
                ...(transactionIds.length
                  ? [{ id: { in: transactionIds } }]
                  : []),
                { sourceType: "PAYROLL_PAYMENT", sourceId: { in: batchIds } },
              ],
            },
            include: paymentTransactionInclude,
          }),
          client.paymentException.findMany({
            where: {
              organizationId: input.organizationId,
              OR: [
                { sourceType: "PAYROLL_PAYMENT", sourceId: { in: batchIds } },
                ...(transactionIds.length
                  ? [{ paymentTransactionId: { in: transactionIds } }]
                  : []),
              ],
            },
            orderBy: { createdAt: "desc" },
          }),
          client.matchRecord.findMany({
            where: {
              organizationId: input.organizationId,
              ...(transactionIds.length
                ? { paymentTransactionId: { in: transactionIds } }
                : { paymentTransactionId: "__none__" }),
            },
            include: matchRecordInclude,
            orderBy: { createdAt: "desc" },
          }),
          client.suspenseItem.findMany({
            where: {
              organizationId: input.organizationId,
              ...(transactionIds.length
                ? { paymentTransactionId: { in: transactionIds } }
                : { paymentTransactionId: "__none__" }),
            },
            orderBy: { createdAt: "desc" },
          }),
          client.paymentReconciliationInboxItem.findMany({
            where: {
              organizationId: input.organizationId,
              ...(transactionIds.length
                ? {
                    OR: [
                      { correlationId: { in: transactionIds } },
                      { externalId: { in: transactionIds } },
                    ],
                  }
                : { id: "__none__" }),
            },
            orderBy: { createdAt: "desc" },
          }),
        ])
      : [[], [], [], [], []];

  return {
    batches,
    transactions,
    exceptions,
    matches,
    suspenseItems,
    inboxItems,
  };
}

buildReadModel.source:
function buildReadModel(input: {
  organizationId: string;
  amountDecision: RedactionDecision;
  providerDecision: RedactionDecision;
  suspenseDecision: RedactionDecision;
  proofIdentifierDecision: RedactionDecision;
  batches: PayrollPaymentBatchRecord[];
  transactions: PaymentTransactionRecord[];
  exceptions: PaymentExceptionRecord[];
  matches: MatchRecordRecord[];
  suspenseItems: SuspenseItemRecord[];
  inboxItems: InboxItemRecord[];
}): PayrollPaymentReconciliationReadModel {
  const transactionsById = new Map(
    input.transactions.map((transaction) => [transaction.id, transaction]),
  );
  const transactionsBySourceId = new Map(
    input.transactions
      .filter(
        (transaction) =>
          transaction.sourceType === "PAYROLL_PAYMENT" && transaction.sourceId,
      )
      .map((transaction) => [transaction.sourceId as string, transaction]),
  );

  const batches = input.batches.map<PayrollPaymentReconciliationBatch>(
    (batch) => {
      const transaction = paymentTransactionForBatch(
        batch,
        transactionsById,
        transactionsBySourceId,
      );
      const batchExceptions = exceptionsForBatch(
        batch,
        transaction,
        input.exceptions,
      );
      const batchMatches = matchesForTransaction(transaction, input.matches);
      const batchSuspenseItems = suspenseForTransaction(
        transaction,
        input.suspenseItems,
      );
      const batchInboxItems = inboxForTransaction(
        transaction,
        input.inboxItems,
      );
      const state = derivedState({
        batch,
        transaction,
        matches: batchMatches,
        exceptions: batchExceptions,
        suspenseItems: batchSuspenseItems,
      });
      const retryAttempts = batchInboxItems.reduce(
        (total, item) => total + item.attempts,
        0,
      );
      const latestRetry = batchInboxItems[0] ?? null;
      const metadata = asRecord(batch.metadata);

      return {
        id: batch.id,
        batchNumber: batch.batchNumber,
        payrollRunId: batch.payrollRunId,
        runNumber: batch.payrollRun.runNumber,
        periodName: batch.payrollRun.payrollPeriod.name,
        status: batch.status,
        reconciliationStatus: batch.reconciliationStatus,
        amount: amount(input.amountDecision, batch.amount),
        currency: batch.currency,
        method: batch.method,
        paymentDate: batch.paymentDate.toISOString(),
        ledgerPostingBatchId: batch.ledgerPostingBatchId,
        postedBusinessEventId: batch.postedBusinessEventId,
        paymentTransactionId: proofIdentifier(
          input.proofIdentifierDecision,
          transaction?.id ?? batch.paymentTransactionId,
        ),
        paymentExceptionId: batch.paymentExceptionId,
        evidenceHash: proofIdentifier(
          input.proofIdentifierDecision,
          batch.evidenceHash,
        ),
        documentHash: proofIdentifier(
          input.proofIdentifierDecision,
          batch.documentHash,
        ),
        bankFileHash: proofIdentifier(
          input.proofIdentifierDecision,
          batch.bankFileHash,
        ),
        derivedState: state,
        nextAction: nextAction(state),
        proof: {
          payrollRegisterSource: "services/payroll/payroll-register.service.ts",
          providerEvidenceRequired: state !== "SETTLED",
          closeImpactSourceCode: "PAYROLL_PAYMENT_RECONCILED",
          componentRegisterProofHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "componentRegisterProofHash"),
          ),
          componentRegisterProofStatus: metadataString(
            metadata,
            "componentRegisterProofStatus",
          ),
          payrollComponentMappingHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "payrollComponentMappingHash"),
          ),
          payrollComponentMappingStatus: metadataString(
            metadata,
            "payrollComponentMappingStatus",
          ),
          yearToDatePolicyHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "yearToDatePolicyHash") ??
              metadataString(asRecord(metadata.yearToDatePolicy), "ytdPolicyHash"),
          ),
          yearToDateAccumulatorHashes: metadataStringList(
            metadata,
            "yearToDateAccumulatorHashes",
          )
            .sort()
            .map((hash) => proofIdentifier(input.proofIdentifierDecision, hash))
            .filter((hash): hash is string => Boolean(hash)),
          paymentAdapterProofHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "paymentAdapterProofHash"),
          ),
          paymentProviderAdapterContractHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "paymentProviderAdapterContractHash"),
          ),
          paymentAdapterStatus: metadataString(metadata, "paymentAdapterStatus"),
          paymentProviderAdapterKey: metadataString(
            metadata,
            "paymentProviderAdapterKey",
          ),
          adapterChaosReleaseGateHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "adapterChaosReleaseGateHash"),
          ),
          productionPaymentAutomationSupported:
            metadata.productionPaymentAutomationSupported === true,
          latestSettlementEvidenceHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "latestSettlementEvidenceHash"),
          ),
          latestSettlementSourceRegisterHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "latestSettlementSourceRegisterHash"),
          ),
          latestSettlementLifecycleContractHash: proofIdentifier(
            input.proofIdentifierDecision,
            metadataString(metadata, "latestSettlementLifecycleContractHash"),
          ),
          latestSettlementLifecycleStatus: metadataString(
            metadata,
            "latestSettlementLifecycleStatus",
          ),
          latestSettlementLifecycleCloseImpact: metadataString(
            metadata,
            "providerSettlementLifecycleCloseImpact",
          ),
          latestSettlementBusinessEventId: metadataString(
            metadata,
            "latestSettlementBusinessEventId",
          ),
          latestSettlementAt: metadataString(metadata, "latestSettlementAt"),
          sourceLinks: [
            {
              type: "PayrollPaymentBatch",
              id: batch.id,
              documentHash: proofIdentifier(
                input.proofIdentifierDecision,
                batch.documentHash,
              ),
              evidenceHash: proofIdentifier(
                input.proofIdentifierDecision,
                batch.evidenceHash,
              ),
            },
            ...batch.allocations.map((allocation) => ({
              type: "PayrollPaymentAllocation",
              id: allocation.id,
              documentHash: proofIdentifier(
                input.proofIdentifierDecision,
                allocation.payslip.documentHash,
              ),
            })),
            ...(transaction
              ? [
                  {
                    type: "PaymentTransaction",
                    id: transaction.id,
                    payloadHash: proofIdentifier(
                      input.proofIdentifierDecision,
                      transaction.payloadHash,
                    ),
                  },
                ]
              : []),
            ...batchMatches.flatMap((match) => [
              { type: "MatchRecord", id: match.id },
              ...(match.providerEvent
                ? [
                    {
                      type: "ProviderEvent",
                      id: match.providerEvent.id,
                      payloadHash: proofIdentifier(
                        input.proofIdentifierDecision,
                        match.providerEvent.rawPayloadHash,
                      ),
                    },
                  ]
                : []),
              ...(match.statementLine
                ? [
                    {
                      type: "StatementLine",
                      id: match.statementLine.id,
                      payloadHash: proofIdentifier(
                        input.proofIdentifierDecision,
                        match.statementLine.rawLineHash,
                      ),
                    },
                  ]
                : []),
            ]),
          ],
        },
        paymentTransaction: transaction
          ? {
              id: transaction.id,
              state: transaction.state,
              providerAccountId: transaction.providerAccountId,
              providerAccountName:
                transaction.providerAccount?.displayName ?? null,
              providerReference: redactText(
                input.providerDecision,
                transaction.providerReference,
              ),
              providerTransactionId: redactText(
                input.providerDecision,
                transaction.providerTransactionId,
              ),
              payloadHash: proofIdentifier(
                input.proofIdentifierDecision,
                transaction.payloadHash,
              ),
              occurredAt: transaction.occurredAt?.toISOString() ?? null,
              confirmedAt: transaction.confirmedAt?.toISOString() ?? null,
              settledAt: transaction.settledAt?.toISOString() ?? null,
            }
          : null,
        matches: batchMatches.map((match) => ({
          id: match.id,
          status: match.status,
          rule: match.rule,
          confidence: decimalString(match.confidence),
          amountMatched: match.amountMatched
            ? amount(input.amountDecision, match.amountMatched)
            : null,
          providerEventId: proofIdentifier(
            input.proofIdentifierDecision,
            match.providerEventId,
          ),
          statementLineId: proofIdentifier(
            input.proofIdentifierDecision,
            match.statementLineId,
          ),
          statementFileHash: proofIdentifier(
            input.proofIdentifierDecision,
            match.statementLine?.statementFile?.fileHash ?? null,
          ),
          reconciliationRunId: match.reconciliationRunId,
        })),
        exceptions: batchExceptions.map((exception) => ({
          id: exception.id,
          type: exception.type,
          severity: exception.severity,
          status: exception.status,
          providerEventId: proofIdentifier(
            input.proofIdentifierDecision,
            exception.providerEventId,
          ),
          statementLineId: proofIdentifier(
            input.proofIdentifierDecision,
            exception.statementLineId,
          ),
          suspenseItemId: exception.suspenseItemId,
          resolvedAt: exception.resolvedAt?.toISOString() ?? null,
        })),
        suspenseItems: batchSuspenseItems.map((item) => ({
          id: item.id,
          type: input.suspenseDecision.allowed
            ? item.type
            : input.suspenseDecision.replacement,
          status: item.status,
          severity: item.severity,
          amount: amount(input.amountDecision, item.amount),
          currency: item.currencyCode,
          nextAction: input.suspenseDecision.allowed
            ? "Resolve or post suspense before settlement."
            : input.suspenseDecision.replacement,
        })),
        retry: {
          available:
            state === "AWAITING_PROVIDER_EVIDENCE" ||
            state === "EXCEPTION_OPEN",
          attempts: retryAttempts,
          nextAttemptAt: latestRetry?.nextAttemptAt?.toISOString() ?? null,
          lastError: input.suspenseDecision.allowed
            ? (latestRetry?.lastError ?? null)
            : latestRetry?.lastError
              ? input.suspenseDecision.replacement
              : null,
        },
      };
    },
  );

  return {
    organizationId: input.organizationId,
    asOf: new Date().toISOString(),
    summary: {
      batchCount: batches.length,
      awaitingProviderEvidence: batches.filter(
        (batch) => batch.derivedState === "AWAITING_PROVIDER_EVIDENCE",
      ).length,
      exceptionOpen: batches.filter(
        (batch) => batch.derivedState === "EXCEPTION_OPEN",
      ).length,
      readyToSettle: batches.filter(
        (batch) => batch.derivedState === "READY_TO_SETTLE",
      ).length,
      partiallySettled: batches.filter(
        (batch) => batch.derivedState === "PARTIALLY_SETTLED",
      ).length,
      settled: batches.filter((batch) => batch.derivedState === "SETTLED")
        .length,
    },
    redaction: {
      amounts: redactionSummary(input.amountDecision),
      providerReferences: redactionSummary(input.providerDecision),
      suspenseDetails: redactionSummary(input.suspenseDecision),
      proofIdentifiers: redactionSummary(input.proofIdentifierDecision),
    },
    batches,
  };
}

getPayrollPaymentReconciliation.source:
export async function getPayrollPaymentReconciliation(
  input: PayrollPaymentReconciliationInput,
  client: DbClient = db,
): Promise<PayrollPaymentReconciliationReadModel> {
  const parsed = payrollPaymentReconciliationInputSchema.parse(input);
  assertReadAllowed(parsed);

  const amountDecision = evaluateRedaction({
    field: "PayrollPaymentReconciliation.amounts",
    category: "payroll_person_amount",
    actorPermissions: parsed.actorPermissions,
    moduleDecision: parsed.moduleDecision,
  });
  const providerDecision = evaluateRedaction({
    field: "PayrollPaymentReconciliation.providerReferences",
    category: "payment_provider_reference",
    actorPermissions: parsed.actorPermissions,
    moduleDecision: parsed.moduleDecision,
  });
  const suspenseDecision = evaluateRedaction({
    field: "PayrollPaymentReconciliation.suspenseDetails",
    category: "reconciliation_suspense_detail",
    actorPermissions: parsed.actorPermissions,
    moduleDecision: parsed.moduleDecision,
  });
  const proofIdentifierDecision = evaluateRedaction({
    field: "PayrollPaymentReconciliation.proofIdentifiers",
    category: "proof_hidden_identifier",
    actorPermissions: parsed.actorPermissions,
    moduleDecision: parsed.moduleDecision,
  });

  const rows = await loadReconciliationRows(
    client as Prisma.TransactionClient,
    parsed,
  );
  const readModel = buildReadModel({
    organizationId: parsed.organizationId,
    amountDecision,
    providerDecision,
    suspenseDecision,
    proofIdentifierDecision,
    ...rows,
  });

  await auditReconciliationRead(client as Prisma.TransactionClient, {
    organizationId: parsed.organizationId,
    actorId: parsed.actorId,
    batchCount: readModel.batches.length,
    amountDecision,
    providerDecision,
    suspenseDecision,
    proofIdentifierDecision,
  });

  return readModel;
}

assertSettlementEvidence.source:
function assertSettlementEvidence(
  parsed: z.output<typeof recordPayrollPaymentSettlementInputSchema>,
  matchRecord: MatchRecordRecord | null,
) {
  if (!parsed.sourceRegisterHash) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires the source payroll register hash.",
    );
  }
  const hasProviderEvidence = Boolean(
    parsed.providerEventId ||
    parsed.statementLineId ||
    parsed.statementFileHash ||
    (matchRecord &&
      (matchRecord.providerEventId || matchRecord.statementLineId)),
  );
  if (!hasProviderEvidence) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires provider event, statement line, or statement file evidence.",
    );
  }
}

assertSettlementState.source:
function assertSettlementState(
  batch: PayrollPaymentBatchRecord,
  transaction: PaymentTransactionRecord,
  openExceptions: PaymentExceptionRecord[],
  matchRecord: MatchRecordRecord | null,
) {
  if (!SETTLEMENT_READY_BATCH_STATUSES.has(batch.status)) {
    throw new BusinessRuleError(
      "Payroll payment settlement can only be recorded for released payment batches.",
    );
  }
  if (!batch.ledgerPostingBatchId || !batch.postedBusinessEventId) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires posted payroll payment ledger evidence.",
    );
  }
  if (
    transaction.sourceType !== "PAYROLL_PAYMENT" ||
    transaction.sourceId !== batch.id
  ) {
    throw new BusinessRuleError(
      "Payment transaction is not linked to the payroll payment batch.",
    );
  }
  if (transaction.state === PaymentTransactionState.SUSPENSE) {
    throw new BusinessRuleError(
      "Payroll payment settlement cannot proceed while the payment transaction is in suspense.",
    );
  }
  if (openExceptions.length > 0 && !matchRecord) {
    throw new BusinessRuleError(
      "Open payroll payment exceptions require approved matching evidence before settlement.",
    );
  }
  if (
    matchRecord &&
    !APPROVED_SETTLEMENT_MATCH_STATUSES.has(matchRecord.status)
  ) {
    throw new BusinessRuleError(
      "Payroll payment settlement requires an approved or auto-matched reconciliation match.",
    );
  }
}

recordPayrollPaymentSettlementEvidence.source:
export async function recordPayrollPaymentSettlementEvidence(
  input: RecordPayrollPaymentSettlementInput,
  client: DbClient = db,
): Promise<PayrollPaymentSettlementResult> {
  const parsed = recordPayrollPaymentSettlementInputSchema.parse(input);
  assertWriteAllowed(parsed);
  const now = parseDate(parsed.now, new Date());

  return inTransaction(client, async (tx) => {
    const batch = await tx.payrollPaymentBatch.findFirst({
      where: {
        id: parsed.payrollPaymentBatchId,
        organizationId: parsed.organizationId,
      },
      include: payrollPaymentBatchInclude,
    });
    if (!batch) throw new NotFoundError("Payroll payment batch not found.");

    const transaction = await tx.paymentTransaction.findFirst({
      where: {
        organizationId: parsed.organizationId,
        OR: [
          ...(batch.paymentTransactionId
            ? [{ id: batch.paymentTransactionId }]
            : []),
          { sourceType: "PAYROLL_PAYMENT", sourceId: batch.id },
        ],
      },
      include: paymentTransactionInclude,
    });
    if (!transaction) {
      throw new BusinessRuleError(
        "Payroll payment batch has no linked payment transaction for reconciliation.",
      );
    }

    const [matchRecord, openExceptions] = await Promise.all([
      parsed.matchRecordId
        ? tx.matchRecord.findFirst({
            where: {
              id: parsed.matchRecordId,
              organizationId: parsed.organizationId,
              paymentTransactionId: transaction.id,
            },
            include: matchRecordInclude,
          })
        : Promise.resolve(null),
      tx.paymentException.findMany({
        where: {
          organizationId: parsed.organizationId,
          status: {
            notIn: [
              PaymentExceptionStatus.RESOLVED,
              PaymentExceptionStatus.DISMISSED,
            ],
          },
          OR: [
            { sourceType: "PAYROLL_PAYMENT", sourceId: batch.id },
            { paymentTransactionId: transaction.id },
          ],
        },
      }),
    ]);

    if (parsed.matchRecordId && !matchRecord) {
      throw new NotFoundError(
        "Payroll payment reconciliation match was not found.",
      );
    }

    assertSettlementEvidence(parsed, matchRecord);
    const proofMetadata = paymentBatchProofMetadata(batch);

    const existingSettlement = asRecord(batch.metadata)[
      settlementMetadataKey(parsed.idempotencyKey)
    ];
    if (existingSettlement) {
      const existing = asRecord(existingSettlement);
      if (existing.inputEvidenceHash !== parsed.evidenceHash) {
        throw new ConflictError(
          "Payroll payment settlement idempotency key was reused with a different evidence hash.",
        );
      }
      if (
        existing.sourceRegisterHash &&
        existing.sourceRegisterHash !== parsed.sourceRegisterHash
      ) {
        throw new ConflictError(
          "Payroll payment settlement idempotency key was reused with a different register proof.",
        );
      }
      return {
        payrollPaymentBatchId: batch.id,
        payrollRunId: batch.payrollRunId,
        status: batch.status,
        reconciliationStatus: batch.reconciliationStatus ?? "SETTLEMENT_REPLAY",
        paymentTransactionId: transaction.id,
        businessEventId: String(existing.businessEventId ?? ""),
        settlementEvidenceHash: String(
          existing.settlementEvidenceHash ?? parsed.evidenceHash,
        ),
        idempotent: true,
      };
    }

    assertSettlementState(batch, transaction, openExceptions, matchRecord);

    const nextBatchStatus =
      parsed.settlementStatus === "settled"
        ? PayrollPaymentBatchStatus.SETTLED
        : PayrollPaymentBatchStatus.PARTIALLY_SETTLED;
    const reconciliationStatus =
      parsed.settlementStatus === "settled" ? "SETTLED" : "PARTIALLY_SETTLED";
    const evidence = settlementPayload({
      parsed,
      batch,
      transaction,
      matchRecord,
      now,
      nextStatus: nextBatchStatus,
      proofMetadata,
    });
    const settlementEvidenceHash = prefixedHash(evidence);
    const settlementLifecycleMetadata = {
      providerSettlementLifecycleContractHash:
        evidence.providerSettlementLifecycleContractHash,
      providerSettlementLifecycleStatus:
        evidence.providerSettlementLifecycleStatus,
      providerSettlementLifecycleCloseImpact:
        evidence.providerSettlementLifecycleCloseImpact,
      providerSettlementLifecycleNextAction:
        evidence.providerSettlementLifecycleNextAction,
      providerSettlementLifecycleContract:
        evidence.providerSettlementLifecycleContract,
    };
    const controlDecision = evaluateSensitiveAction({
      action: "payroll.payment.reconcile",
      actorId: parsed.actorId ?? null,
      organizationId: parsed.organizationId,
      actorPermissions: parsed.actorPermissions,
      subjectActorId:
        batch.releasedById ?? batch.approvedById ?? batch.requestedById,
      lastAuthAt: parsed.lastAuthAt,
      now,
      resourceType: "PayrollPaymentBatch",
      resourceId: batch.id,
      amount: parsed.settlementAmount ?? batch.amount,
      currency: batch.currency,
      metadata: {
        settlementStatus: parsed.settlementStatus,
        sourceRegisterHash: parsed.sourceRegisterHash,
        ...proofMetadata,
        ...settlementLifecycleMetadata,
        paymentTransactionId: transaction.id,
        matchRecordId: matchRecord?.id ?? null,
        openExceptionCount: openExceptions.length,
      },
    });
    await auditSensitiveActionDecision(tx, controlDecision);
    assertSensitiveActionAllowed(controlDecision);

    const updatedTransaction = await tx.paymentTransaction.update({
      where: { id: transaction.id },
      data: {
        state:
          parsed.settlementStatus === "settled"
            ? PaymentTransactionState.SETTLED
            : PaymentTransactionState.CONFIRMED,
        providerAccountId:
          parsed.providerAccountId ?? transaction.providerAccountId,
        providerTransactionId:
          parsed.providerTransactionId ?? transaction.providerTransactionId,
        providerReference:
          parsed.providerReference ?? transaction.providerReference,
        confirmedAt: transaction.confirmedAt ?? now,
        settledAt:
          parsed.settlementStatus === "settled" ? now : transaction.settledAt,
        metadata: safeJson({
          ...asRecord(transaction.metadata),
          ...proofMetadata,
          ...settlementLifecycleMetadata,
          latestPayrollSettlementEvidenceHash: settlementEvidenceHash,
          latestPayrollSettlementSourceRegisterHash: parsed.sourceRegisterHash,
          latestPayrollSettlementComponentRegisterProofHash:
            proofMetadata.componentRegisterProofHash,
          latestPayrollSettlementPayrollComponentMappingHash:
            proofMetadata.payrollComponentMappingHash,
          latestPayrollSettlementProviderAdapterProofHash:
            proofMetadata.paymentAdapterProofHash,
          latestPayrollSettlementProviderAdapterContractHash:
            proofMetadata.paymentProviderAdapterContractHash,
          latestPayrollSettlementLifecycleContractHash:
            evidence.providerSettlementLifecycleContractHash,
          latestPayrollSettlementLifecycleStatus:
            evidence.providerSettlementLifecycleStatus,
          latestPayrollSettlementAt: now.toISOString(),
          latestPayrollSettlementStatus: parsed.settlementStatus,
        }),
      },
    });

    if (openExceptions.length > 0) {
      await tx.paymentException.updateMany({
        where: {
          id: { in: openExceptions.map((exception) => exception.id) },
          organizationId: parsed.organizationId,
        },
        data: {
          status: PaymentExceptionStatus.RESOLVED,
          resolvedAt: now,
          resolutionNotes: "Resolved by payroll payment settlement evidence.",
          providerEventId:
            parsed.providerEventId ?? matchRecord?.providerEventId ?? undefined,
          statementLineId:
            parsed.statementLineId ?? matchRecord?.statementLineId ?? undefined,
          reconciliationRunId:
            parsed.reconciliationRunId ??
            matchRecord?.reconciliationRunId ??
            undefined,
          metadata: safeJson({
            settlementEvidenceHash,
            sourceRegisterHash: parsed.sourceRegisterHash,
            ...proofMetadata,
            ...settlementLifecycleMetadata,
            payrollPaymentBatchId: batch.id,
          }),
        },
      });
    }

    const eventResult = await recordBusinessEventInTx(
      tx as unknown as BusinessEventTx,
      {
        organizationId: parsed.organizationId,
        eventType: "payroll.payment_batch.reconciled",
        eventSource: "INTERNAL",
        schemaVersion: 1,
        idempotencyKey: `payroll-payment-reconciliation:${batch.id}:${parsed.idempotencyKey}`,
        payload: {
          payrollPaymentBatchId: batch.id,
          payrollRunId: batch.payrollRunId,
          batchNumber: batch.batchNumber,
          previousStatus: batch.status,
          nextStatus: nextBatchStatus,
          reconciliationStatus,
          settlementEvidenceHash,
          sourceRegisterHash: parsed.sourceRegisterHash,
          ...proofMetadata,
          ...settlementLifecycleMetadata,
          paymentTransactionId: updatedTransaction.id,
          paymentTransactionState: updatedTransaction.state,
          matchRecordId: matchRecord?.id ?? null,
          providerEventId:
            parsed.providerEventId ?? matchRecord?.providerEventId ?? null,
          statementLineId:
            parsed.statementLineId ?? matchRecord?.statementLineId ?? null,
          statementFileHash:
            parsed.statementFileHash ??
            matchRecord?.statementLine?.statementFile?.fileHash ??
            null,
        },
        occurredAt: now,
        actorId: parsed.actorId ?? undefined,
        sourceType: AccountingSourceType.PAYROLL_PAYMENT,
        sourceId: batch.id,
        postingBatchId: batch.ledgerPostingBatchId ?? undefined,
        documentHash: settlementEvidenceHash,
        metadata: {
          gate: "aqstoqflow-hrpayroll-17-payment-reconciliation",
          settlementEvidenceHash,
          sourceRegisterHash: parsed.sourceRegisterHash,
          ...proofMetadata,
          ...settlementLifecycleMetadata,
          closeImpactSourceCode: "PAYROLL_PAYMENT_RECONCILED",
        },
        outboxMessages: [
          {
            channel: "NOTIFICATION",
            eventName: "payroll_payment_batch.reconciled",
            destination: "accounting",
            payload: {
              severity:
                parsed.settlementStatus === "settled" ? "info" : "warning",
              payrollPaymentBatchId: batch.id,
              payrollRunId: batch.payrollRunId,
              reconciliationStatus,
              paymentTransactionId: updatedTransaction.id,
            },
          },
        ],
      },
    );
    await markBusinessEventAppliedInTx(
      tx as unknown as BusinessEventTx,
      parsed.organizationId,
      eventResult.event.id,
    );

    const updatedBatch = await tx.payrollPaymentBatch.update({
      where: { id: batch.id },
      data: {
        status: nextBatchStatus,
        reconciliationStatus,
        paymentExceptionId: null,
        metadata: safeJson({
          ...asRecord(batch.metadata),
          ...proofMetadata,
          ...settlementLifecycleMetadata,
          latestSettlementEvidenceHash: settlementEvidenceHash,
          latestSettlementSourceRegisterHash: parsed.sourceRegisterHash,
          latestSettlementComponentRegisterProofHash:
            proofMetadata.componentRegisterProofHash,
          latestSettlementPayrollComponentMappingHash:
            proofMetadata.payrollComponentMappingHash,
          latestSettlementProviderAdapterProofHash:
            proofMetadata.paymentAdapterProofHash,
          latestSettlementProviderAdapterContractHash:
            proofMetadata.paymentProviderAdapterContractHash,
          latestSettlementLifecycleContractHash:
            evidence.providerSettlementLifecycleContractHash,
          latestSettlementLifecycleStatus:
            evidence.providerSettlementLifecycleStatus,
          latestSettlementBusinessEventId: eventResult.event.id,
          latestSettlementAt: now.toISOString(),
          latestSettlementStatus: parsed.settlementStatus,
          [settlementMetadataKey(parsed.idempotencyKey)]: {
            businessEventId: eventResult.event.id,
            inputEvidenceHash: parsed.evidenceHash,
            sourceRegisterHash: parsed.sourceRegisterHash,
            ...proofMetadata,
            componentRegisterProofHash:
              proofMetadata.componentRegisterProofHash,
            payrollComponentMappingHash:
              proofMetadata.payrollComponentMappingHash,
            paymentAdapterProofHash: proofMetadata.paymentAdapterProofHash,
            paymentProviderAdapterContractHash:
              proofMetadata.paymentProviderAdapterContractHash,
            providerSettlementLifecycleContractHash:
              evidence.providerSettlementLifecycleContractHash,
            providerSettlementLifecycleStatus:
              evidence.providerSettlementLifecycleStatus,
            settlementEvidenceHash,
          },
          requestedMetadata: parsed.metadata ?? null,
        }),
      },
    });

    await recordCloseCertificationInvalidationsForSourceInTx(
      tx,
      parsed.organizationId,
      {
        sourceCode: "PAYROLL_PAYMENT_RECONCILED",
        sourceId: batch.id,
        periodId:
          batch.payrollRun.payrollPeriod.accountingPeriodId ?? undefined,
        periodStart: batch.paymentDate,
        periodEnd: batch.paymentDate,
        staleReason:
          "Payroll payment settlement evidence changed certified close evidence.",
        newEvidenceHash: settlementEvidenceHash,
        correlationId: eventResult.event.id,
      },
      {
        actorId: parsed.actorId ?? null,
        now,
      },
    );

    await tx.auditLog.create({
      data: {
        entityType: "PayrollPaymentBatch",
        entityId: batch.id,
        action: "PAYROLL_PAYMENT_RECONCILIATION_RECORDED",
        userId: parsed.actorId ?? null,
        organizationId: parsed.organizationId,
        changes: safeJson({
          before: {
            status: batch.status,
            reconciliationStatus: batch.reconciliationStatus,
            paymentTransactionState: transaction.state,
          },
          after: {
            status: updatedBatch.status,
            reconciliationStatus: updatedBatch.reconciliationStatus,
            paymentTransactionState: updatedTransaction.state,
            settlementEvidenceHash,
            sourceRegisterHash: parsed.sourceRegisterHash,
            ...proofMetadata,
            ...settlementLifecycleMetadata,
            businessEventId: eventResult.event.id,
          },
        }),
      },
    });

    return {
      payrollPaymentBatchId: updatedBatch.id,
      payrollRunId: updatedBatch.payrollRunId,
      status: updatedBatch.status,
      reconciliationStatus:
        updatedBatch.reconciliationStatus ?? reconciliationStatus,
      paymentTransactionId: updatedTransaction.id,
      businessEventId: eventResult.event.id,
      settlementEvidenceHash,
      idempotent: false,
    };
  });
}

