function isValidIanaTimezone(value: string) {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value }).format(
      new Date("2026-01-01T00:00:00.000Z"),
    )
    return true
  } catch {
    return false
  }
}

currencyMinorUnit.source:
function currencyMinorUnit(currency: string) {
  try {
    const minorUnit = new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
    }).resolvedOptions().maximumFractionDigits
    return typeof minorUnit === "number" ? minorUnit : null
  } catch {
    return null
  }
}

resolveOrganizationAnalyticalContext.source:
export function resolveOrganizationAnalyticalContext(
  input: ResolveOrganizationAnalyticalContextInput,
): OrganizationAnalyticalContextResult {
  const blockers: AnalyticalContextBlocker[] = []
  const organizationId = input.organizationId?.trim() ?? ""
  const currency = input.currency?.trim().toUpperCase() ?? ""
  const timezone = input.timezone?.trim() ?? ""
  const generatedAt = normalizeExplicitInstant(input.generatedAt)
  const periodStart = normalizeExplicitInstant(input.periodStart)
  const periodEndExclusive = normalizeExplicitInstant(input.periodEndExclusive)

  if (!organizationId) {
    blockers.push(
      blocker(
        "MISSING_ORGANIZATION_ID",
        "organizationId",
        "An organization is required for analytical context.",
      ),
    )
  }

  const minorUnit = ISO_CURRENCY_PATTERN.test(currency)
    ? currencyMinorUnit(currency)
    : null

  if (minorUnit === null) {
    blockers.push(
      blocker(
        "INVALID_CURRENCY",
        "currency",
        "The organization currency must be an explicit three-letter currency code.",
      ),
    )
  }

  if (!timezone || !isValidIanaTimezone(timezone)) {
    blockers.push(
      blocker(
        "INVALID_TIMEZONE",
        "timezone",
        "The organization timezone must be an explicit IANA timezone.",
      ),
    )
  }

  if (!generatedAt) {
    blockers.push(
      blocker(
        "INVALID_GENERATED_AT",
        "generatedAt",
        "The analytical generation time must be an instant with an explicit UTC offset.",
      ),
    )
  }

  if (!periodStart) {
    blockers.push(
      blocker(
        "INVALID_PERIOD_START",
        "periodStart",
        "The analytical period start must be an instant with an explicit UTC offset.",
      ),
    )
  }

  if (!periodEndExclusive) {
    blockers.push(
      blocker(
        "INVALID_PERIOD_END",
        "periodEndExclusive",
        "The analytical period end must be an exclusive instant with an explicit UTC offset.",
      ),
    )
  }

  if (
    periodStart &&
    periodEndExclusive &&
    new Date(periodEndExclusive).getTime() <= new Date(periodStart).getTime()
  ) {
    blockers.push(
      blocker(
        "INVALID_PERIOD_ORDER",
        "periodEndExclusive",
        "The analytical period end must be later than its start.",
      ),
    )
  }

  const hasExplicitLocation = input.locationId !== undefined && input.locationId !== null
  const locationId = input.locationId?.trim() ?? ""
  if (hasExplicitLocation && !locationId) {
    blockers.push(
      blocker(
        "INVALID_LOCATION_SCOPE",
        "locationId",
        "An explicit location scope requires a non-empty location identifier.",
      ),
    )
  }

  if (
    blockers.length > 0 ||
    minorUnit === null ||
    !generatedAt ||
    !periodStart ||
    !periodEndExclusive
  ) {
    return { state: "blocked", context: null, blockers }
  }

  return {
    state: "ready",
    blockers: [],
    context: {
      schemaVersion: ORGANIZATION_ANALYTICAL_CONTEXT_SCHEMA_VERSION,
      organizationId,
      generatedAt,
      currency: {
        code: currency,
        minorUnit,
        source: "ORGANIZATION",
        aggregationPrecision: "DECIMAL_SOURCE_AGGREGATION",
      },
      timezone: {
        iana: timezone,
        calendar: "gregory",
        source: "ORGANIZATION",
      },
      period: {
        periodStart,
        periodEndExclusive,
        boundaryConvention: "INCLUSIVE_START_EXCLUSIVE_END",
        timezone,
      },
      scope: locationId
        ? { kind: "LOCATION", locationId }
        : { kind: "ORGANIZATION", locationId: null },
    },
  }
}

calendar.source:
function calendar(value: string) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) throw new BusinessRuleError("Choose a valid calendar date.")
  const instant = new Date(`${value}T00:00:00.000Z`)
  if (!Number.isFinite(instant.getTime()) || instant.toISOString().slice(0, 10) !== value) throw new BusinessRuleError("Choose a valid calendar date.")
  return instant
}

dailySalesPeriod.source:
export function dailySalesPeriod(date: string | Date | undefined, timezone: string, now = new Date()) {
  let formatter: Intl.DateTimeFormat
  try {
    if (!timezone.trim()) throw new Error("Missing timezone")
    formatter = new Intl.DateTimeFormat("en-CA", { timeZone: timezone, calendar: "gregory", numberingSystem: "latn", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" })
  } catch { throw new BusinessRuleError("A valid organization timezone is required for the daily report.") }
  const parts = (instant: Date) => Object.fromEntries(formatter.formatToParts(instant).filter(part => part.type !== "literal").map(part => [part.type, part.value]))
  const key = (instant: Date) => {
    if (!Number.isFinite(instant.getTime())) throw new BusinessRuleError("Choose a valid calendar date.")
    const value = parts(instant)
    return `${value.year}-${value.month}-${value.day}`
  }
  const selectedDate = typeof date === "string" ? date : key(date ?? now)
  const calendarDate = calendar(selectedDate)
  const nextDate = new Date(calendarDate.getTime() + 86_400_000).toISOString().slice(0, 10)
  const midnight = (value: string) => {
    const target = calendar(value).getTime()
    const wallTime = (instant: number) => {
      const p = parts(new Date(instant))
      return Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}.000Z`)
    }
    let candidate = target
    for (let attempt = 0; attempt < 4; attempt++) {
      const delta = target - wallTime(candidate)
      candidate += delta
      if (delta === 0) {
        for (let offset = -180; offset <= 180; offset += 15) if (offset !== 0 && wallTime(candidate + offset * 60_000) === target) throw new BusinessRuleError("The selected day has an ambiguous midnight in the organization timezone.")
        return new Date(candidate)
      }
    }
    throw new BusinessRuleError("The selected day has no resolvable midnight in the organization timezone.")
  }
  return { date: selectedDate, calendarDate, start: midnight(selectedDate), endExclusive: midnight(nextDate) }
}

