    return err<{ id: string }>(safeLoggedActionErrorMessage(
      "Error archiving managed terminal",
      error,
      { action: "archiveManagedTerminal" },
      getActionErrorMessage(error, "Failed to deactivate terminal"),
    ))
  }
}

