readInvitationRoleOptions.source:
export async function readInvitationRoleOptions(input: {
  organizationId: string
  actorId: string
  actorPermissions: readonly string[]
  locale: "en" | "fr"
}): Promise<InvitationRoleOptions> {
  if (!input.organizationId?.trim() || !input.actorId?.trim()) throw new BusinessRuleError("Organization scope and current actor are required")
  const unavailable = (state: InvitationOptionsState): InvitationRoleOptions => ({ state, roles: [], checkedAt: new Date().toISOString() })
  if (!evaluateRoleGrantAuthority(input.actorPermissions).allowed) return unavailable("forbidden")
  // Keep the existing role-read boundary; assigning roles does not silently
  // grant a new permission to enumerate the organization's role definitions.
  if (!hasRbacPermission(input.actorPermissions, "roles.read")) return unavailable("roles_read_required")

  return db.$transaction(async tx => {
    const organization = await tx.organization.findFirst({
      where: { id: input.organizationId, isActive: true, deletedAt: null },
      select: { id: true },
    })
    if (!organization) return unavailable("organization_unavailable")
    const issuer = await readCurrentInvitationIssuer(tx, { organizationId: input.organizationId, actorId: input.actorId, role: { organizationId: input.organizationId, permissions: [] } })
    if (!issuer) return unavailable("forbidden")
    if (!hasRbacPermission(issuer.permissions, "roles.read")) return unavailable("roles_read_required")
    const roles = await tx.role.findMany({
      where: { organizationId: input.organizationId },
      orderBy: [{ code: "asc" }, { id: "asc" }],
      select: { id: true, organizationId: true, code: true, nameEn: true, nameFr: true, permissions: true },
    })
    const grantable = roles.filter(role => evaluateRoleGrantPolicy({
      actorOrganizationId: input.organizationId,
      actorPermissions: issuer.permissions,
      targetRole: role,
    }).allowed).map(role => ({
      value: role.id,
      label: (input.locale === "fr" ? role.nameFr || role.nameEn : role.nameEn || role.nameFr) || role.code,
    }))
    return { state: grantable.length ? "ready" : "empty", roles: grantable, checkedAt: new Date().toISOString() }
  }, { isolationLevel: Prisma.TransactionIsolationLevel.RepeatableRead })
}

permissionEvidence.source:
function permissionEvidence(permissions: readonly string[]): RoleGrantPermissionEvidence[] {
  return permissions.map((permission) => ({
    permission,
    risk: permission === "*" ? "crit" : permissionRisk(permission),
  }))
}

evaluateRoleGrantAuthority.source:
export function evaluateRoleGrantAuthority(
  actorPermissions: readonly string[],
): RoleGrantPolicyDecision {
  const missingPermissions = INVITATION_ROLE_GRANT_PERMISSIONS.filter(
    (permission) => !canGrantRolePermission(actorPermissions, permission),
  )

  if (missingPermissions.length > 0) {
    return {
      allowed: false,
      reasonCode: "MISSING_GRANT_AUTHORITY",
      risk: ROLE_GRANT_RISK,
      deniedPermissions: permissionEvidence(missingPermissions),
      safeMessage: "You are not allowed to invite users with roles",
    }
  }

  return {
    allowed: true,
    reasonCode: "GRANT_AUTHORITY_CONFIRMED",
    risk: ROLE_GRANT_RISK,
    deniedPermissions: [],
    safeMessage: null,
  }
}

evaluateRoleGrantPolicy.source:
export function evaluateRoleGrantPolicy(input: RoleGrantPolicyInput): RoleGrantPolicyDecision {
  const authorityDecision = evaluateRoleGrantAuthority(input.actorPermissions)
  if (!authorityDecision.allowed) return authorityDecision

  if (input.targetRole.organizationId !== input.actorOrganizationId) {
    return {
      allowed: false,
      reasonCode: "CROSS_TENANT_ROLE",
      risk: ROLE_GRANT_RISK,
      deniedPermissions: [],
      safeMessage: "Invalid role for this organization",
    }
  }

  if (input.targetRole.permissions.includes("*")) {
    return {
      allowed: false,
      reasonCode: "TARGET_ROLE_WILDCARD",
      risk: ROLE_GRANT_RISK,
      deniedPermissions: permissionEvidence(["*"]),
      safeMessage: "You cannot grant the selected role",
    }
  }

  const explicitActorPermissions = input.actorPermissions.filter(
    (permission) => permission !== "*",
  )
  const ungrantablePermissions = input.targetRole.permissions.filter(
    (permission) => !canGrantRolePermission(explicitActorPermissions, permission),
  )

  if (ungrantablePermissions.length > 0) {
    return {
      allowed: false,
      reasonCode: "ACTOR_GRANT_CEILING_EXCEEDED",
      risk: ROLE_GRANT_RISK,
      deniedPermissions: permissionEvidence(ungrantablePermissions),
      safeMessage: "You cannot grant the selected role",
    }
  }

  return {
    allowed: true,
    reasonCode: "ROLE_GRANT_ALLOWED",
    risk: ROLE_GRANT_RISK,
    deniedPermissions: [],
    safeMessage: null,
  }
}

