export function invitationEmailV1(payload: InvitationDeliveryPayload, email: string, token: string) {
  const link = `${payload.baseUrl}/${payload.locale}/user-invite/invitation?token=${encodeURIComponent(token)}`
  const subject = payload.locale === "fr" ? `Invitation à rejoindre ${payload.companyName}` : `Invitation to join ${payload.companyName}`
  const text = payload.locale === "fr"
    ? `Vous êtes invité(e) à rejoindre ${payload.companyName} dans Stoquify avec le rôle ${payload.roleName}.

Créez votre compte :
${link}

Ce lien expire le ${payload.expiresAt} (UTC). Vos accès dépendent du rôle autorisé.
Si vous ne reconnaissez pas cette invitation, contactez votre administrateur et ne partagez pas ce lien.`
    : `You are invited to join ${payload.companyName} in Stoquify with the ${payload.roleName} role.

Create your account:
${link}

This link expires at ${payload.expiresAt} (UTC). Your access depends on the authorized role.
If you do not recognize this invitation, contact your administrator and do not share this link.`
  return { from: payload.from, to: email, subject, text }
}

